package com.personalbis;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;

public class BankScanner
{
    private final Client client;
    private final ItemManager itemManager;

    @Inject
    public BankScanner(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;
    }

    public List<BankItem> scan()
    {
        List<BankItem> result = new ArrayList<>();
        ItemContainer bank = client.getItemContainer(InventoryID.BANK);

        if (bank == null)
        {
            return result;
        }

        for (Item item : bank.getItems())
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }

            ItemComposition definition = client.getItemDefinition(item.getId());
            // Bank placeholders can be represented with a positive container
            // quantity even though the bank widget displays zero. Exclude the
            // placeholder item variant using its definition metadata.
            if (definition.getPlaceholderTemplateId() >= 0)
            {
                continue;
            }

            // Keep the snapshot cheap, but preserve the item name because Slayer
            // equipment detection and owned-supply selection are name based.
            // Client item definitions are already cached by RuneLite.
            // Preserve the real dose-specific item definition. Canonicalising here
            // turns every potion dose into the 4-dose name, so an owned (2) dose
            // can be mistaken for a zero-quantity (4) placeholder later.
            String name = definition.getName();
            result.add(new BankItem(item.getId(), item.getQuantity(), name == null ? "" : name));
        }

        return result;
    }

    /**
     * Builds the ownership pool used by the equipment optimisers. The bank
     * snapshot remains the source of truth for the Recommended bank view, but
     * worn and carried items are still owned and must be eligible gear.
     */
    public List<BankItem> scanOwnedGear(List<BankItem> bankSnapshot)
    {
        Map<Integer, BankItem> owned = new LinkedHashMap<>();
        if (bankSnapshot != null)
        {
            for (BankItem item : bankSnapshot)
            {
                merge(owned, item.getItemId(), item.getQuantity(), item.getName());
            }
        }
        appendContainer(owned, client.getItemContainer(InventoryID.INV));
        appendContainer(owned, client.getItemContainer(InventoryID.WORN));
        return new ArrayList<>(owned.values());
    }

    private void appendContainer(Map<Integer, BankItem> owned, ItemContainer container)
    {
        if (container == null) return;
        for (Item item : container.getItems())
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) continue;
            ItemComposition definition = client.getItemDefinition(item.getId());
            String name = definition.getName();
            merge(owned, item.getId(), item.getQuantity(), name == null ? "" : name);
        }
    }

    private static void merge(Map<Integer, BankItem> owned, int itemId, int quantity, String name)
    {
        if (itemId <= 0 || quantity <= 0) return;
        BankItem previous = owned.get(itemId);
        int total = quantity + (previous == null ? 0 : previous.getQuantity());
        String resolvedName = name == null || name.isEmpty()
            ? (previous == null ? "" : previous.getName()) : name;
        owned.put(itemId, new BankItem(itemId, total, resolvedName));
    }
}

package com.personalbis;
import java.util.Map;
public final class BestStyleSelection {
 private BestStyleSelection(){}
 public static AttackStyle best(Map<AttackStyle,Double> scores){
  AttackStyle best=null; double score=Double.NEGATIVE_INFINITY;
  for(AttackStyle s:AttackStyle.values()){double v=scores.getOrDefault(s,Double.NEGATIVE_INFINITY);if(v>score){score=v;best=s;}}
  return best;
 }
}

package com.personalbis;

import java.util.*;
import com.personalbis.wiki.WikiEquipment;
import com.personalbis.BlowpipeAmmoPlan.Pipe;
import com.personalbis.BlowpipeAmmoPlan.Dart;

/** Adapts explicit ammo assumptions into calculator-only candidates. */
public final class BlowpipeAmmoCandidates
{
    private BlowpipeAmmoCandidates() {}
    /** Marker keeps manual internal ammo separate from genuinely owned loose darts. */
    public static final class AssumedDart extends EquipmentCandidate
    {
        public final Pipe pipe;
        private AssumedDart(Pipe pipe,Dart dart,WikiEquipment item)
        {
            super(new BankItem(dart.itemId,1,dart.label),EquipmentSlot.AMMO,item.bonuses.ranged_str,
                0,0,0,item.bonuses.ranged_str,0,0f,0,0,false,"Assumed internal dart",
                RequirementResult.usable("Player-selected internal ammo; contents/count not detected"));
            this.pipe=pipe;
        }
    }

    public static boolean matches(EquipmentCandidate weapon,EquipmentCandidate ammo)
    {
        return weapon!=null&&ammo instanceof AssumedDart
            &&((AssumedDart)ammo).pipe==BlowpipeAmmoPlan.pipe(weapon.getItem().getItemId());
    }

    public static Map<EquipmentSlot,List<EquipmentCandidate>> withAssumptions(
        Map<EquipmentSlot,List<EquipmentCandidate>> ranked,Map<Pipe,Dart> selections,Set<Pipe> scanned)
    {
        Map<EquipmentSlot,List<EquipmentCandidate>> result=new EnumMap<>(EquipmentSlot.class);
        result.putAll(ranked);
        List<EquipmentCandidate> ammo=new ArrayList<>(ranked.getOrDefault(EquipmentSlot.AMMO,Collections.emptyList()));
        for(Pipe pipe:scanned){Dart dart=selections.get(pipe);if(!pipe.accepts(dart))continue;
            WikiEquipment item=WikiEquipmentEngine.canonicalItem(dart.itemId);
            if(item!=null&&item.bonuses!=null)ammo.add(new AssumedDart(pipe,dart,item));
        }
        result.put(EquipmentSlot.AMMO,ammo);
        return result;
    }
}

package com.personalbis;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import net.runelite.client.config.ConfigManager;

/** Swing-only view of explicit ammo assumptions. Visibility uses personal bank scans. */
final class BlowpipeAmmoOptions extends JPanel
{
    private final ConfigManager config;
    private final Runnable changed;
    private Map<BlowpipeAmmoPlan.Pipe,BlowpipeAmmoPlan.Dart> selections;
    private Set<BlowpipeAmmoPlan.Pipe> scanned=EnumSet.noneOf(BlowpipeAmmoPlan.Pipe.class);
    private boolean restoring;

    BlowpipeAmmoOptions(ConfigManager config,Runnable changed)
    {
        this.config=config;this.changed=changed;
        setOpaque(false);setLayout(new BoxLayout(this,BoxLayout.Y_AXIS));
        setAlignmentX(Component.LEFT_ALIGNMENT);
        selections=BlowpipeAmmoPlan.decode(config.getConfiguration("personalbis",BlowpipeAmmoPlan.CONFIG_KEY));
        setVisible(false);
    }

    void refresh(List<BankItem> bank)
    {
        Set<BlowpipeAmmoPlan.Pipe> next=BlowpipeAmmoPlan.scannedPipes(bank);
        if(next.equals(scanned))return;
        scanned=next;rebuild();
    }

    void reload()
    {
        selections=BlowpipeAmmoPlan.decode(config.getConfiguration("personalbis",BlowpipeAmmoPlan.CONFIG_KEY));
        rebuild();
    }

    Map<BlowpipeAmmoPlan.Pipe,BlowpipeAmmoPlan.Dart> snapshot()
    {
        Map<BlowpipeAmmoPlan.Pipe,BlowpipeAmmoPlan.Dart> result=new EnumMap<>(BlowpipeAmmoPlan.Pipe.class);
        for(BlowpipeAmmoPlan.Pipe pipe:scanned)if(selections.containsKey(pipe))result.put(pipe,selections.get(pipe));
        return Collections.unmodifiableMap(result);
    }

    private void rebuild()
    {
        restoring=true;removeAll();
        for(BlowpipeAmmoPlan.Pipe pipe:scanned)
        {
            JLabel label=new JLabel(pipe.label+" Ammo");label.setForeground(new Color(255,215,0));label.setFont(net.runelite.client.ui.FontManager.getRunescapeFont());
            label.setAlignmentX(Component.LEFT_ALIGNMENT);add(label);
            JComboBox<BlowpipeAmmoPlan.Dart> box=new JComboBox<>(BlowpipeAmmoPlan.options(pipe).toArray(new BlowpipeAmmoPlan.Dart[0]));
            SidebarStyle.combo(box);
            box.setToolTipText("<html><body style='width:200px'>Manual ammo assumption; loaded contents and quantity are unknown. Select darts, then regenerate.</body></html>");
            box.setSelectedItem(selections.getOrDefault(pipe,BlowpipeAmmoPlan.Dart.UNKNOWN));
            box.setAlignmentX(Component.LEFT_ALIGNMENT);box.setMaximumSize(new Dimension(Integer.MAX_VALUE,28));
            box.addActionListener(e->{if(restoring)return;
                BlowpipeAmmoPlan.Dart dart=(BlowpipeAmmoPlan.Dart)box.getSelectedItem();
                if(pipe.accepts(dart))selections.put(pipe,dart);else selections.remove(pipe);
                config.setConfiguration("personalbis",BlowpipeAmmoPlan.CONFIG_KEY,BlowpipeAmmoPlan.encode(selections));
                changed.run();
            });
            add(box);add(Box.createVerticalStrut(5));
        }
        setVisible(!scanned.isEmpty());restoring=false;revalidate();repaint();
    }
}

package com.personalbis;

import java.util.*;


/** Explicit player assumptions about internal darts, never detected item contents. */
public final class BlowpipeAmmoPlan
{
    public static final String CONFIG_KEY="blowpipeAmmo";
    private BlowpipeAmmoPlan() {}

    public enum Pipe
    {
        TOXIC("Toxic blowpipe",9,12924,12926),
        BLAZING("Blazing blowpipe",9,28687,28688),
        CAMPHOR("Camphor blowpipe",5,31575,31577),
        IRONWOOD("Ironwood blowpipe",6,31579,31581),
        ROSEWOOD("Rosewood blowpipe",7,31583,31585),
        DRYGORE("Drygore blowpipe",9,30373,30374);
        public final String label;
        private final int maxTier;
        private final int[] ids;
        Pipe(String label,int maxTier,int... ids){this.label=label;this.maxTier=maxTier;this.ids=ids;}
        public boolean accepts(Dart dart){return dart!=null&&dart!=Dart.UNKNOWN&&dart.tier<=maxTier;}
    }

    public enum Dart
    {
        UNKNOWN("Not selected",0,0), BRONZE("Bronze dart",1,806), IRON("Iron dart",2,807),
        STEEL("Steel dart",3,808), BLACK("Black dart",4,3093), MITHRIL("Mithril dart",5,809),
        ADAMANT("Adamant dart",6,810), RUNE("Rune dart",7,811),
        AMETHYST("Amethyst dart",8,25849), DRAGON("Dragon dart",9,11230);
        public final String label;
        public final int itemId;
        private final int tier;
        Dart(String label,int tier,int itemId){this.label=label;this.tier=tier;this.itemId=itemId;}
        @Override public String toString(){return label;}
    }

    public static Pipe pipe(int itemId)
    {
        for(Pipe pipe:Pipe.values())for(int id:pipe.ids)if(itemId==id)return pipe;
        return null;
    }

    public static Set<Pipe> scannedPipes(List<BankItem> bank)
    {
        Set<Pipe> found=EnumSet.noneOf(Pipe.class);
        if(bank!=null)for(BankItem item:bank)if(item!=null&&item.getQuantity()>0){
            Pipe p=pipe(item.getItemId());if(p!=null)found.add(p);
        }
        return found;
    }

    public static List<Dart> options(Pipe pipe)
    {
        List<Dart> options=new ArrayList<>();options.add(Dart.UNKNOWN);
        for(Dart dart:Dart.values())if(pipe.accepts(dart))options.add(dart);
        return Collections.unmodifiableList(options);
    }

    public static Map<Pipe,Dart> decode(String raw)
    {
        Map<Pipe,Dart> result=new EnumMap<>(Pipe.class);
        if(raw!=null)for(String entry:raw.split(",")){
            String[] parts=entry.split(":");if(parts.length!=2)continue;
            try{Pipe pipe=Pipe.valueOf(parts[0]);Dart dart=Dart.valueOf(parts[1]);
                if(pipe.accepts(dart))result.put(pipe,dart);
            }catch(IllegalArgumentException ignored){}
        }
        return result;
    }

    public static String encode(Map<Pipe,Dart> selections)
    {
        StringJoiner result=new StringJoiner(",");
        for(Pipe pipe:Pipe.values()){Dart dart=selections.get(pipe);
            if(pipe.accepts(dart))result.add(pipe.name()+":"+dart.name());}
        return result.toString();
    }

}

