    JSpinner spinner=new JSpinner(new SpinnerNumberModel(selected.amount(type),0,type.maximum,1));SidebarStyle.spinner(spinner);spinner.setToolTipText(tooltip);((JSpinner.DefaultEditor)spinner.getEditor()).getTextField().setToolTipText(tooltip);spinner.setPreferredSize(new Dimension(60,26));spinners.put(type,spinner);
    String compact=type==DefenceReductionPlan.Type.BGS?"BGS damage":type==DefenceReductionPlan.Type.DWH?"Warhammer hits":type.label;
    JLabel label=new JLabel(compact);label.setToolTipText(tooltip);label.setFont(FontManager.getRunescapeFont());label.setForeground(SidebarStyle.TEXT);
    row.add(spinner,BorderLayout.WEST);row.add(label,BorderLayout.CENTER);add(row);
    spinner.addChangeListener(e->update(type,((Number)spinner.getValue()).intValue()));
   }
  }
  resetButton.setEnabled(activeCount()>0);add(resetButton);add(Box.createVerticalStrut(5));
  setVisible(hasOptions());restoring=false;revalidate();repaint();
 }
}

