package com.personalbis;

public final class FinalLoadoutSelection
{
    private FinalLoadoutSelection(){}

    public static boolean better(double candidateDps, double currentDps)
    {
        return Double.isFinite(candidateDps) &&
            (!Double.isFinite(currentDps) || candidateDps > currentDps);
    }

    /** Finite-fight ordering: lower expected TTK wins, sustained DPS breaks ties. */
    public static boolean betterTtk(double candidateTtk, double candidateDps,
        double currentTtk, double currentDps)
    {
        if (!Double.isFinite(candidateTtk)) return !Double.isFinite(currentTtk) && candidateDps>0 && better(candidateDps,currentDps);
        if (!Double.isFinite(currentTtk)) return true;
        int ttk = Double.compare(candidateTtk,currentTtk);
        return ttk < 0 || (ttk == 0 && better(candidateDps,currentDps));
    }
}

package com.personalbis;

import java.util.*;

/** Offline TFA planning. HP formula is provisional, fitted to supplied Wiki tables.
 * No live mechanics, incoming damage, movement or encounter simulation. */
final class FracturedArchiveRules {
    private FracturedArchiveRules() {}
    private static final Set<Integer> IDS=new HashSet<>(Arrays.asList(16659,16660,16640,16641,16652,
        16665,16666,16667,16670,16643,16645,16647,16650,16684,16687,16688,
        16673,16674,16675,16677,16678,16679,16680,16681));
    static boolean isTfa(MonsterDefinition m){return m!=null&&IDS.contains(m.getId());}
    static boolean blade(MonsterDefinition m){return m!=null&&m.getId()==16675;}
    static boolean imp(MonsterDefinition m){return m!=null&&m.getId()==16650;}
    enum BorkPhase {
        FULL("Smork HP 100% - 75%"), HIGH("Smork HP 75% - 50%"),
        LOW("Smork HP 50% - 25%"), EMPTY("Smork HP 25% - 0%"), STUNNED("Stunned");
        private final String label;
        BorkPhase(String label){this.label=label;}
        @Override public String toString(){return label;}
    }
    static boolean isBork(MonsterDefinition m){return m!=null&&m.getId()==16640;}
    static MonsterDefinition withBorkPhase(MonsterDefinition m,BorkPhase phase){
        if(!isBork(m))return m;
        int delta=phase==BorkPhase.STUNNED?100:0;
        return new MonsterDefinition(m.getId(),m.getName(),phase.toString(),m.getCombatLevel(),
            m.getDefenceLevel(),m.getMagicLevel(),m.getRangedLevel(),m.getHitpoints(),
            m.getStabDefence()-delta,m.getSlashDefence()-delta,m.getCrushDefence()-delta,
            m.getMagicDefence(),m.getLightDefence(),m.getStandardDefence(),m.getHeavyDefence(),
            m.getAttributes(),m.getSize(),m.getWeaknessElement(),m.getWeaknessSeverity(),m.getMagicAttack());
    }
    static boolean hpSupported(MonsterDefinition m){
        if(m==null)return false;
        switch(m.getId()){
            case 16659:case 16660:case 16640:case 16641:case 16652:case 16665:case 16684:
            case 16673:case 16674:case 16677:return true;
            default:return false;
        }
    }
    static int hp(int base,int party){
        int n=Math.max(2,Math.min(8,party));
        if(n==2)return base;
        // Percent arithmetic followed by nearest-ten rounding, ties upward.
        return (int)(((long)base*(145+42*(n-3))+500)/1000)*10;
    }
    static MonsterDefinition scale(MonsterDefinition m,int party){
        if(!isTfa(m))return m;
        List<String> a=new ArrayList<>(m.getAttributes());
        a.removeIf(x->x.startsWith("tfa_party:")||x.startsWith("flat_armour:")&&m.getId()==16640);
        a.add("tfa_party:"+Math.max(2,Math.min(8,party)));
        int base=m.getHitpoints();
        if(m.getId()==16659&&m.getVersion().equalsIgnoreCase("Grounded"))base=1100;
        if(hpSupported(m))a.add("tfa_scaled_hp");
        return new MonsterDefinition(m.getId(),m.getName(),m.getVersion(),m.getCombatLevel(),m.getDefenceLevel(),
            m.getMagicLevel(),m.getRangedLevel(),hpSupported(m)?hp(base,party):base,
            m.getStabDefence(),m.getSlashDefence(),m.getCrushDefence(),m.getMagicDefence(),m.getLightDefence(),
            m.getStandardDefence(),m.getHeavyDefence(),a,m.getSize(),m.getWeaknessElement(),m.getWeaknessSeverity(),m.getMagicAttack());
    }
    static int floor(MonsterDefinition m){
        if(m==null)return -1;
        switch(m.getId()){
            case 16659:case 16660:return 156;case 16652:return 120;case 16640:return 180;
            case 16667:return 117;case 16684:return 102;case 16673:case 16674:return 129;case 16677:return 150;
            case 16641:case 16665:case 16643:case 16645:case 16647:case 16675:return 0;
            default:return -1;
        }
    }
    static int borkStage(MonsterDefinition m){
        if(!isBork(m)||BorkPhase.STUNNED.toString().equals(m.getVersion()))return -1;
        for(BorkPhase phase:BorkPhase.values())
            if(phase.toString().equals(m.getVersion()))return phase.ordinal();
        return 0;
    }
    static HitDistribution transform(HitDistribution d,MonsterDefinition m,AttackStyle style){
        int stage=borkStage(m);
        if(stage>=0){
            // Wiki excerpt and upstream disagree on initial Magic resistance.
            // Use upstream's 0/2/4/6 pending confirmation; documented in tooltip.
            int reduction=style==AttackStyle.MAGIC?2*stage:8+2*stage;
            d=d.transform(HitDistribution.flatAdd(-reduction,0),false);
        }
        return d;
    }
    static String note(MonsterDefinition m){
        if(!isTfa(m))return "";
        String s="TFA: static target estimate; HP scaling is provisional. No movement, team DPS, healing or encounter timing is simulated.";
        if(!hpSupported(m)&&!blade(m))s+=" Team-size HP scaling is not verified for this target; bundled HP is used.";
        if(blade(m))s+=" The Blade: melee recommendations excluded because of phase mechanics. DPS comparison only; phase duration and 50% transfer to phase 3 are not modelled. TTK unavailable.";
        if(m.getId()==16677)s+=" Phase 3 baseline; phase 4 shares base stats but prayers, rear bonus and conditional reductions are not modelled. Phase-2 damage transfer is excluded.";
        if(m.getId()==16665)s+=" No add-clear time or healing is included.";
        if(m.getId()==16652)s+=" Ezekiel enrage damage reduction is not modelled.";
        if(m.getId()==16640)s+=" Bork armour stages 1–4 correspond to Smorks HP 100–75%, 75–50%, 50–25% and 25–0%. Magic resistance follows upstream (0/2/4/6); the supplied Wiki prose conflicts. Stunned subtracts 100 from each melee defence bonus; alleged rear bonus excluded.";
        if(m.getId()==16643||m.getId()==16645||m.getId()==16647)s+=" Shared shield pool: estimate is for one depletion, not the full five-cycle encounter.";
        return s;
    }
}

package com.personalbis;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.IntFunction;
import java.util.function.Supplier;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.events.ItemContainerChanged;

/** Client-thread snapshot logic, shared by future real and synthetic storage listeners. */
public final class GroupStorageSnapshot
{
    private volatile List<BankItem> items = Collections.emptyList();
    private volatile Instant capturedAt;

    /**
     * Group Ironman account types from the account-type varbit: 4 Group, 5 Hardcore Group,
     * 6 Unranked Group. These accounts have group storage.
     */
    static boolean isGroupIronman(int accountTypeVarbit)
    {
        return accountTypeVarbit >= 4 && accountTypeVarbit <= 6;
    }

    public boolean capture(ItemContainerChanged event, IntFunction<ItemComposition> definitions, Supplier<Instant> clock)
    {
        if (event.getContainerId() != InventoryID.INV_GROUP_TEMP || event.getItemContainer() == null) return false;
        List<BankItem> next = new ArrayList<>();
        for (Item item : event.getItemContainer().getItems())
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) continue;
            ItemComposition definition = definitions.apply(item.getId());
            if (definition == null) throw new IllegalStateException("Missing item definition " + item.getId());
            if (definition.getPlaceholderTemplateId() >= 0) continue;
            next.add(new BankItem(item.getId(), item.getQuantity(), definition.getName() == null ? "" : definition.getName()));
        }
        // Publish only after processing the whole event; never retain its mutable array.
        Instant timestamp = clock.get();
        items = Collections.unmodifiableList(next);
        capturedAt = timestamp;
        return true;
    }

    public boolean hasSnapshot() { return capturedAt != null; }
    public Instant getCapturedAt() { return capturedAt; }
    public List<BankItem> getItems() { return items; }
    public void clear() { items = Collections.emptyList(); capturedAt = null; }
}

package com.personalbis;

import java.util.*;
import java.util.function.Function;

/**
 * Integer hitsplat distribution model ported from the OSRS Wiki DPS calculator HitDist layer.
 * Keeps accuracy state separate from damage so target transforms can operate per hitsplat.
 */
public final class HitDistribution {
    public static final class Hitsplat {
        public final int damage;
        public final boolean accurate;
        public Hitsplat(int damage, boolean accurate){ this.damage=damage; this.accurate=accurate; }
    }
    public static final class WeightedHit {
        public final double probability;
        public final List<Hitsplat> hitsplats;
        public WeightedHit(double probability,List<Hitsplat> hitsplats){this.probability=probability;this.hitsplats=Collections.unmodifiableList(new ArrayList<>(hitsplats));}
        int sum(){int s=0;for(Hitsplat h:hitsplats)s+=h.damage;return s;}
        boolean anyAccurate(){for(Hitsplat h:hitsplats)if(h.accurate)return true;return false;}
    }
    public interface Transformer extends Function<Hitsplat,HitDistribution>{}
    private final List<WeightedHit> hits;
    public HitDistribution(List<WeightedHit> hits){this.hits=Collections.unmodifiableList(new ArrayList<>(hits));}
    public List<WeightedHit> hits(){return hits;}

    public static HitDistribution linear(double accuracy,int minimum,int maximum){
        List<WeightedHit> out=new ArrayList<>();
        double p=accuracy/(maximum-minimum+1.0);
        for(int i=minimum;i<=maximum;i++)out.add(new WeightedHit(p,Collections.singletonList(new Hitsplat(i,true))));
        if(accuracy!=1.0)out.add(new WeightedHit(1.0-accuracy,Collections.singletonList(new Hitsplat(0,false))));
        return new HitDistribution(out);
    }
    /** Wiki modern successful-zero conversion: an accurate zero becomes one. */
    public HitDistribution accurateZeroToOne(){return transform(h->single(Math.max(1,h.damage),h.accurate),false);}
    public HitDistribution transform(Transformer t){return transform(t,true);}
    public HitDistribution transform(Transformer t,boolean transformInaccurate){
        List<WeightedHit> out=new ArrayList<>();
        for(WeightedHit wh:hits){
            HitDistribution acc=new HitDistribution(Collections.singletonList(new WeightedHit(wh.probability,Collections.emptyList())));
            for(Hitsplat h:wh.hitsplats){
                HitDistribution part=(!h.accurate&&!transformInaccurate)?single(h.damage,false):t.apply(h);
                acc=acc.zip(part);
            }
            out.addAll(acc.hits);
        }
        return new HitDistribution(out).flatten();
    }
    public HitDistribution zip(HitDistribution other){
        List<WeightedHit> out=new ArrayList<>();
        for(WeightedHit a:hits)for(WeightedHit b:other.hits){List<Hitsplat> hs=new ArrayList<>(a.hitsplats);hs.addAll(b.hitsplats);out.add(new WeightedHit(a.probability*b.probability,hs));}
        return new HitDistribution(out);
    }
    public HitDistribution flatten(){
        Map<String,Double> probs=new LinkedHashMap<>(); Map<String,List<Hitsplat>> lists=new LinkedHashMap<>();
        for(WeightedHit wh:hits){StringBuilder k=new StringBuilder();for(Hitsplat h:wh.hitsplats)k.append(h.damage).append(':').append(h.accurate?'1':'0').append(';');String key=k.toString();probs.put(key,probs.getOrDefault(key,0.0)+wh.probability);lists.putIfAbsent(key,wh.hitsplats);}
        List<WeightedHit> out=new ArrayList<>();for(Map.Entry<String,Double> e:probs.entrySet())if(e.getValue()>0)out.add(new WeightedHit(e.getValue(),lists.get(e.getKey())));return new HitDistribution(out);
    }
    public HitDistribution cumulative(){
        Map<String,Double> probs=new LinkedHashMap<>();
        for(WeightedHit wh:hits){String key=wh.sum()+":"+(wh.anyAccurate()?1:0);probs.put(key,probs.getOrDefault(key,0.0)+wh.probability);}
        List<WeightedHit> out=new ArrayList<>();for(Map.Entry<String,Double> e:probs.entrySet()){String[] p=e.getKey().split(":");out.add(new WeightedHit(e.getValue(),Collections.singletonList(new Hitsplat(Integer.parseInt(p[0]),"1".equals(p[1])))));}return new HitDistribution(out);
    }
    public double expectedHit(){double v=0;for(WeightedHit wh:hits)v+=wh.probability*wh.sum();return v;}
    public int size(){return hits.size();}
    /** Wiki HitDist.scaleProbability. */
    public HitDistribution scaleProbability(double factor){List<WeightedHit> out=new ArrayList<>();for(WeightedHit wh:hits)out.add(new WeightedHit(wh.probability*factor,wh.hitsplats));return new HitDistribution(out);}
    /** Wiki HitDist.scaleDamage with per-hitsplat truncation. */
    public HitDistribution scaleDamage(int numerator,int divisor){if(divisor==0)throw new IllegalArgumentException("divisor");List<WeightedHit> out=new ArrayList<>();for(WeightedHit wh:hits){List<Hitsplat> hs=new ArrayList<>();for(Hitsplat h:wh.hitsplats)hs.add(new Hitsplat((int)(((long)h.damage*numerator)/divisor),h.accurate));out.add(new WeightedHit(wh.probability,hs));}return new HitDistribution(out);}
    public HitDistribution scaleDamage(int factor){return scaleDamage(factor,1);}
    public int min(){int v=Integer.MAX_VALUE;for(WeightedHit wh:hits)v=Math.min(v,wh.sum());return v==Integer.MAX_VALUE?0:v;}
    public int max(){int v=Integer.MIN_VALUE;for(WeightedHit wh:hits)v=Math.max(v,wh.sum());return v==Integer.MIN_VALUE?0:v;}
    public double probability(){double p=0;for(WeightedHit wh:hits)p+=wh.probability;return p;}

    public static HitDistribution single(int damage,boolean accurate){return new HitDistribution(Collections.singletonList(new WeightedHit(1.0,Collections.singletonList(new Hitsplat(damage,accurate)))));}
    /** Wiki HitDistribution.single(accuracy, hitsplats). */
    public static HitDistribution single(double accuracy,List<Hitsplat> hitsplats){List<WeightedHit> out=new ArrayList<>();out.add(new WeightedHit(accuracy,hitsplats));if(accuracy!=1.0)out.add(new WeightedHit(1.0-accuracy,Collections.singletonList(new Hitsplat(0,false))));return new HitDistribution(out);}
    public static Transformer flatLimit(int maximum,int minimum){return h->single(Math.max(minimum,Math.min(h.damage,maximum)),h.accurate);}
    public static Transformer multiply(int numerator,int divisor,int minimum){return h->{int d=(numerator*h.damage)/divisor;if(minimum!=0)d=h.damage>=minimum?Math.max(minimum,d):Math.max(h.damage,d);return single(d,h.accurate);};}
    public static Transformer divide(int divisor,int minimum){return multiply(1,divisor,minimum);}
    public static Transformer flatAdd(int addend,int minimum){return h->single(Math.max(minimum,h.damage+addend),h.accurate);}
    public static Transformer linearMin(int maximum,int offset){return h->{List<WeightedHit> out=new ArrayList<>();double p=1.0/(maximum+1.0);for(int i=0;i<=maximum;i++)out.add(new WeightedHit(p,Collections.singletonList(new Hitsplat(Math.min(h.damage,i+offset),h.accurate))));return new HitDistribution(out).flatten();};}
    public static Transformer cappedReroll(int limit,int rollMax,int offset){return h->{if(h.damage<=limit)return single(h.damage,h.accurate);List<WeightedHit> out=new ArrayList<>();double p=1.0/(rollMax+1.0);for(int i=0;i<=rollMax;i++)out.add(new WeightedHit(p,Collections.singletonList(new Hitsplat(i+offset,h.accurate))));return new HitDistribution(out).flatten();};}

    /** Structural port of Wiki HitDist.AttackDistribution. */
    public static final class AttackDistribution {
        private final List<HitDistribution> dists;
        public AttackDistribution(List<HitDistribution> dists){this.dists=new ArrayList<>(dists);}
        public List<HitDistribution> dists(){return Collections.unmodifiableList(dists);}
        public void addDist(HitDistribution d){dists.add(d);}
        /** Total damage after per-hitsplat transforms. Convolve independent components
         * numerically instead of materialising their Cartesian product of hitsplats.
         * Correlated hits within each WeightedHit stay together before convolution.
         */
        public double[] damageProbabilities(){
            double[] total={1.0};
            for(HitDistribution component:dists){
                CalculationCancellation.check();
                int maximum=0;
                for(WeightedHit hit:component.hits)maximum=Math.max(maximum,Math.max(0,hit.sum()));
                double[] part=new double[maximum+1];
                for(WeightedHit hit:component.hits)part[Math.max(0,hit.sum())]+=hit.probability;
                double[] next=new double[total.length+part.length-1];
                for(int a=0;a<total.length;a++)if(total[a]!=0.0)
                    for(int b=0;b<part.length;b++)if(part[b]!=0.0)next[a+b]+=total[a]*part[b];
                total=next;
            }
            return total;
        }
        public HitDistribution zipped(){if(dists.isEmpty())return HitDistribution.single(0,false);HitDistribution r=dists.get(0);for(int i=1;i<dists.size();i++)r=r.zip(dists.get(i));return r;}
        public HitDistribution singleHitsplat(){if(dists.isEmpty())return HitDistribution.single(0,false);HitDistribution r=dists.get(0);for(int i=1;i<dists.size();i++)r=r.zip(dists.get(i)).cumulative();return r;}
        public AttackDistribution transform(Transformer t,boolean transformInaccurate){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.transform(t,transformInaccurate));return new AttackDistribution(o);}
        public AttackDistribution flatten(){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.flatten());return new AttackDistribution(o);}
        public AttackDistribution scaleProbability(double f){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.scaleProbability(f));return new AttackDistribution(o);}
        public AttackDistribution scaleDamage(int n,int div){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.scaleDamage(n,div));return new AttackDistribution(o);}
        public int min(){int v=0;for(HitDistribution d:dists)v+=d.min();return v;} public int max(){int v=0;for(HitDistribution d:dists)v+=d.max();return v;} public double expectedDamage(){double v=0;for(HitDistribution d:dists)v+=d.expectedHit();return v;}
        public AttackDistribution firstHitMax(){if(dists.isEmpty())return this;HitDistribution first=dists.get(0);int mx=0;for(WeightedHit wh:first.hits)if(!wh.hitsplats.isEmpty()&&wh.hitsplats.get(0).accurate)mx=Math.max(mx,wh.hitsplats.get(0).damage);List<WeightedHit> hs=new ArrayList<>();for(WeightedHit wh:first.hits){if(wh.hitsplats.isEmpty()||!wh.hitsplats.get(0).accurate){hs.add(wh);continue;}List<Hitsplat> spl=new ArrayList<>(wh.hitsplats);spl.set(0,new Hitsplat(mx,true));hs.add(new WeightedHit(wh.probability,spl));}List<HitDistribution> o=new ArrayList<>();o.add(new HitDistribution(hs).flatten());o.addAll(dists.subList(1,dists.size()));return new AttackDistribution(o);}
        public AttackDistribution firstHitAccurate(){if(dists.isEmpty())return this;List<WeightedHit> hs=new ArrayList<>();double p=0;for(WeightedHit wh:dists.get(0).hits)if(!wh.hitsplats.isEmpty()&&wh.hitsplats.get(0).accurate){hs.add(wh);p+=wh.probability;}if(p==0)return this;List<HitDistribution> o=new ArrayList<>();o.add(new HitDistribution(hs).scaleProbability(1.0/p));o.addAll(dists.subList(1,dists.size()));return new AttackDistribution(o);}
        public AttackDistribution firstHitMinimum(int minimum){if(dists.isEmpty())return this;List<HitDistribution> o=new ArrayList<>();o.add(dists.get(0).transform(h->HitDistribution.single(Math.max(h.damage,minimum),h.accurate),false));o.addAll(dists.subList(1,dists.size()));return new AttackDistribution(o).flatten();}
    }

}

package com.personalbis;

import java.util.Collection;
import com.personalbis.wiki.WikiEquipment;

/** Encounter parts and per-hitsplat tail transforms from the Wiki DPS calculator. */
public final class HueycoatlRules
{
    private HueycoatlRules() {}

    static boolean nonAttackable(int id) { return id == 14011 || id == 14015; }
    static String part(int id, String version)
    {
        if (id == 14017) return "Body (phase 1)";
        if (id == 14009 || id == 14010 || id == 14013) return "Head";
        if (id == 14014) return "Tail";
        return version;
    }

    /** Crush must be strictly higher than all other offensive bonuses, across all gear. */
    static boolean qualifyingCrush(AttackStyle style, Collection<EquipmentCandidate> gear)
    {
        if (style != AttackStyle.MELEE_CRUSH || gear == null) return false;
        int stab = 0, slash = 0, crush = 0, ranged = 0, magic = 0;
        for (EquipmentCandidate c : gear)
        {
            if (c == null) continue;
            WikiEquipment item = WikiEquipmentEngine.canonicalItem(c.getItem().getItemId());
            if (item == null) return false; // Do not infer other attack bonuses from a style-specific candidate.
            if (item.offensive == null) continue;
            stab += item.offensive.stab;
            slash += item.offensive.slash;
            crush += item.offensive.crush;
            ranged += item.offensive.ranged;
            magic += item.offensive.magic;
        }
        return crush > stab && crush > slash && crush > ranged && crush > magic;
    }

    static HitDistribution tail(HitDistribution d, MonsterDefinition monster,
        AttackStyle style, String element, boolean qualifyingCrush)
    {
        if (monster == null || monster.getId() != 14014) return d;
        boolean crush = style == AttackStyle.MELEE_CRUSH && qualifyingCrush;
        d = d.transform(HitDistribution.linearMin(crush ? 9 : 4, 0));
        if (crush) d = d.transform(h -> h.damage > 0
            ? HitDistribution.single(h.damage, h.accurate)
            : HitDistribution.single(1, true));
        return d.flatten();
    }
}

package com.personalbis;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;
import java.util.List;
import java.util.ArrayList;
import java.util.function.IntFunction;

/** Immutable name policy captured once per manual loadout generation. */
public final class ItemExclusionList
{
    private final Set<String> names;

    public ItemExclusionList(String text)
    {
        Set<String> parsed = new LinkedHashSet<>();
        if (text != null)
            for (String entry : text.split("[,\\r\\n]+"))
            {
                String name = normalise(entry);
                if (!name.isEmpty()) parsed.add(name);
            }
        names = Collections.unmodifiableSet(parsed);
    }

    private static String normalise(String name)
    {
        return name == null ? "" : name.trim().toLowerCase(Locale.ROOT)
            .replaceAll("\\s+", " ").replaceFirst("\\([1-4]\\)$", "").trim();
    }

    public boolean excludes(String name, String canonicalName)
    {
        return names.contains(normalise(name)) || names.contains(normalise(canonicalName));
    }

    public boolean sameAs(ItemExclusionList other)
    {
        return other != null && names.equals(other.names);
    }

    public List<BankItem> filter(List<BankItem> owned, IntFunction<String> canonicalNames)
    {
        List<BankItem> allowed = new ArrayList<>();
        for (BankItem item : owned)
            if (!excludes(item.getName(), canonicalNames.apply(item.getItemId()))) allowed.add(item);
        return allowed;
    }
}

package com.personalbis;

import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

@Singleton
public final class ItemExclusions
{
    public static final String KEY = "excludedItems";
    public static final String MENU_OPTION = "Exclude from My BiS Finder";
    private final ConfigManager config;
    private final ItemManager items;

    @Inject
    public ItemExclusions(ConfigManager config, ItemManager items)
    {
        this.config = config;
        this.items = items;
    }

    public ItemExclusionList snapshot()
    {
        return new ItemExclusionList(config.getConfiguration("personalbis", KEY));
    }

    // Item definition and canonicalisation calls belong on the client thread.
    public String nameFor(int itemId)
    {
        ItemComposition definition = items.getItemComposition(items.canonicalize(itemId));
        return definition.getName();
    }

    public void exclude(int itemId)
    {
        if (itemId <= 0) return;
        String name = nameFor(itemId);
        if (name == null || name.isEmpty() || snapshot().excludes(name, name)) return;
        String current = config.getConfiguration("personalbis", KEY);
        config.setConfiguration("personalbis", KEY,
            current == null || current.trim().isEmpty() ? name : current.trim() + ", " + name);
    }

    public List<BankItem> filter(List<BankItem> owned, ItemExclusionList policy)
    {
        return policy.filter(owned, this::nameFor);
    }
}

package com.personalbis;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Eligibility checks used by the equipment intelligence layer.
 *
 * r0.3.0 includes a working requirement framework plus common high-value gear
 * rules. Unknown item-specific requirements are marked UNVERIFIED instead of
 * being silently treated as known-good. The complete generated OSRS requirement
 * table is the next data-layer milestone.
 */
public class ItemRequirementRegistry
{
    private final Client client;

    @Inject
    public ItemRequirementRegistry(Client client)
    {
        this.client = client;
    }

    public RequirementResult check(BankItem item, EquipmentSlot slot)
    {
        String name = item.getName().toLowerCase();
        Map<Skill, Integer> required = inferCommonLevelRequirements(name, slot);

        for (Map.Entry<Skill, Integer> requirement : required.entrySet())
        {
            int current = client.getRealSkillLevel(requirement.getKey());
            if (current < requirement.getValue())
            {
                return RequirementResult.blocked(
                    "Requires " + requirement.getValue() + " " + pretty(requirement.getKey()) +
                    " (you have " + current + ")");
            }
        }

        QuestCheck questCheck = inferQuestRequirement(name);
        if (questCheck != null)
        {
            try
            {
                Quest quest = Quest.valueOf(questCheck.questEnumName);
                if (quest.getState(client) != QuestState.FINISHED)
                {
                    return RequirementResult.blocked("Requires quest: " + quest.getName());
                }
            }
            catch (IllegalArgumentException ignored)
            {
                return RequirementResult.unverified("Quest requirement could not be verified");
            }
        }

        if (required.isEmpty() && questCheck == null)
        {
            return RequirementResult.unverified("Equipable; specific skill/quest requirements not yet verified");
        }

        return RequirementResult.usable("Meets known level/quest requirements");
    }

    private Map<Skill, Integer> inferCommonLevelRequirements(String name, EquipmentSlot slot)
    {
        Map<Skill, Integer> req = new HashMap<>();
        if(name.equals("obligator"))req.put(Skill.ATTACK,85);
        if(name.equals("ascension crossbows"))req.put(Skill.RANGED,80);
        if(name.equals("zorya's tome"))req.put(Skill.MAGIC,85);
        if(name.equals("rondache"))req.put(Skill.DEFENCE,80);

        if (name.contains("rune "))
        {
            req.put(isArmourSlot(slot) ? Skill.DEFENCE : Skill.ATTACK, 40);
        }
        if (name.contains("dragon "))
        {
            req.put(isArmourSlot(slot) ? Skill.DEFENCE : Skill.ATTACK, 60);
        }

        if (containsAny(name, "dharok", "guthan", "karil", "ahrim", "torag", "verac")) req.put(Skill.DEFENCE, 70);
        if (name.contains("bandos chestplate") || name.contains("bandos tassets")) req.put(Skill.DEFENCE, 65);
        // Dragonhide / clue ranged armour. These checks are important because
        // offensive stats alone can otherwise make unavailable gear look best.
        if (containsAny(name, "black d'hide", "black dragonhide"))
        {
            req.put(Skill.RANGED, 70);
            if (slot == EquipmentSlot.BODY || slot == EquipmentSlot.SHIELD)
            {
                req.put(Skill.DEFENCE, 40);
            }
        }
        if (containsAny(name,
            "ancient d'hide", "armadyl d'hide", "bandos d'hide",
            "guthix d'hide", "saradomin d'hide", "zamorak d'hide",
            "ancient coif", "armadyl coif", "bandos coif",
            "guthix coif", "saradomin coif", "zamorak coif",
            "ancient bracers", "armadyl bracers", "bandos bracers",
            "guthix bracers", "saradomin bracers", "zamorak bracers",
            "ancient chaps", "armadyl chaps", "bandos chaps",
            "guthix chaps", "saradomin chaps", "zamorak chaps",
            "ancient boots", "armadyl boots", "bandos boots",
            "guthix boots", "saradomin boots", "zamorak boots"))
        {
            req.put(Skill.RANGED, 70);
            if (slot != EquipmentSlot.LEGS && slot != EquipmentSlot.HANDS)
            {
                req.put(Skill.DEFENCE, 40);
            }
        }
        if (name.contains("blue d'hide")) req.put(Skill.RANGED, 50);
        if (name.contains("red d'hide")) req.put(Skill.RANGED, 60);
        if (name.contains("green d'hide")) req.put(Skill.RANGED, 40);

        if (containsAny(name, "karil's", "karils")) { req.put(Skill.RANGED, 70); req.put(Skill.DEFENCE, 70); }
        if (containsAny(name, "armadyl helmet", "armadyl chestplate", "armadyl chainskirt")) { req.put(Skill.RANGED, 70); req.put(Skill.DEFENCE, 70); }
        if (name.contains("crystal helm") || name.contains("crystal body") || name.contains("crystal legs"))
        {
            req.put(Skill.RANGED, 70);
            req.put(Skill.DEFENCE, 70);
        }
        if (name.contains("slayer helmet") || name.contains("slayer helm") || name.contains("black mask"))
        {
            req.put(Skill.DEFENCE, 10);
        }
        if (name.contains("masori")) req.put(Skill.RANGED, 80);
        if (name.contains("ancestral")) { req.put(Skill.MAGIC, 75); req.put(Skill.DEFENCE, 65); }
        if (name.contains("torva")) { req.put(Skill.DEFENCE, 80); req.put(Skill.STRENGTH, 80); }
        if (name.contains("abyssal whip")) req.put(Skill.ATTACK, 70);
        if (name.contains("abyssal tentacle")) req.put(Skill.ATTACK, 75);
        if (name.contains("godsword")) req.put(Skill.ATTACK, 75);
        if (name.contains("scythe of vitur")) { req.put(Skill.ATTACK, 80); req.put(Skill.STRENGTH, 90); }
        if (name.contains("bow of faerdhinen")) req.put(Skill.RANGED, 80);
        if (name.contains("twisted bow")) req.put(Skill.RANGED, 85);
        if (name.contains("toxic blowpipe")) req.put(Skill.RANGED, 75);
        if (name.contains("dragon hunter crossbow")) req.put(Skill.RANGED, 70);
        if (name.contains("trident of the seas")) req.put(Skill.MAGIC, 75);
        if (name.contains("trident of the swamp")) req.put(Skill.MAGIC, 78);
        if (name.contains("sanguinesti staff")) req.put(Skill.MAGIC, 82);
        if (name.contains("tumeken's shadow")) req.put(Skill.MAGIC, 85);

        return req;
    }

    private QuestCheck inferQuestRequirement(String name)
    {
        if (name.contains("dragon scimitar")) return new QuestCheck("MONKEY_MADNESS_I");
        if (name.contains("barrows gloves")) return new QuestCheck("RECIPE_FOR_DISASTER");
        if (name.contains("ava's assembler")) return new QuestCheck("DRAGON_SLAYER_II");
        if (name.contains("mythical cape")) return new QuestCheck("DRAGON_SLAYER_II");
        if (name.contains("crystal helm") || name.contains("crystal body") || name.contains("crystal legs") || name.contains("bow of faerdhinen")) return new QuestCheck("SONG_OF_THE_ELVES");
        return null;
    }

    private boolean isArmourSlot(EquipmentSlot slot)
    {
        return slot == EquipmentSlot.HEAD || slot == EquipmentSlot.BODY || slot == EquipmentSlot.LEGS || slot == EquipmentSlot.SHIELD || slot == EquipmentSlot.HANDS || slot == EquipmentSlot.FEET;
    }

    private boolean containsAny(String text, String... terms)
    {
        for (String term : terms)
        {
            if (text.contains(term)) return true;
        }
        return false;
    }

    private String pretty(Skill skill)
    {
        String lower = skill.name().toLowerCase();
        return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
    }

    private static final class QuestCheck
    {
        private final String questEnumName;
        private QuestCheck(String questEnumName) { this.questEnumName = questEnumName; }
    }
}

package com.personalbis;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

/** Explicit task/species/area membership; separate from broad highlight aliases. */
final class KonarTargetCatalogue
{
    private static volatile Pack PACK;

    static synchronized void initialize(Gson gson)
    {
        if (PACK == null) PACK = load(gson);
    }
    private static final class Pack
    {
        String combatSourceSha256;
        Map<String, Map<String, List<Rule>>> tasks;
    }
    private static final class Rule { String name; List<Integer> automaticIds; }

    private static Pack load(Gson gson)
    {
        try (InputStream in = KonarTargetCatalogue.class.getResourceAsStream("/slayer-data/konar-targets.json"))
        {
            if (in == null) throw new IllegalStateException("Missing Konar target definitions");
            Pack pack = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Pack.class);
            // Weekly combat updates must not reuse a uniqueness conclusion
            // established against different levels/stats. Membership remains
            // useful, but automatic resolutions wait for recompilation.
            try (InputStream combat = KonarTargetCatalogue.class.getResourceAsStream("/wiki-data/monsters.json"))
            {
                java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
                byte[] buffer = new byte[8192];
                int length;
                while ((length = combat.read(buffer)) != -1) digest.update(buffer, 0, length);
                StringBuilder hash = new StringBuilder();
                for (byte value : digest.digest()) hash.append(String.format("%02x", value & 0xff));
                if (!hash.toString().equals(pack.combatSourceSha256))
                    pack.tasks.values().stream().flatMap(a -> a.values().stream()).flatMap(List::stream)
                        .forEach(r -> r.automaticIds = java.util.Collections.emptyList());
            }
            catch (java.security.NoSuchAlgorithmException ex) { throw new IllegalStateException(ex); }
            return pack;
        }
        catch (java.io.IOException ex) { throw new IllegalStateException("Cannot load Konar target definitions", ex); }
    }

    private static Map<String, List<Rule>> task(String task)
    {
        for (Map.Entry<String, Map<String, List<Rule>>> entry : PACK.tasks.entrySet())
            if (SlayerTaskCatalogue.singular(entry.getKey()).equals(SlayerTaskCatalogue.singular(task)))
                return entry.getValue();
        return null;
    }

    static boolean listed(String task, MonsterDefinition monster)
    {
        Map<String, List<Rule>> areas = task(task);
        return areas != null && areas.values().stream().flatMap(List::stream)
            .anyMatch(r -> r.name.equalsIgnoreCase(monster.getName()));
    }

    /** null means keep using exact spawn/manual evidence for this permitted species. */
    static SlayerAssignmentLocation.Eligibility decision(String task, String location, MonsterDefinition monster)
    {
        String area = SlayerAssignmentLocation.normalize(location);
        if (area.isEmpty() || area.equals("wilderness")) return null;
        Map<String, List<Rule>> areas = task(task);
        if (areas == null) return null;
        List<Rule> rules = null;
        for (Map.Entry<String, List<Rule>> entry : areas.entrySet())
            if (SlayerAssignmentLocation.normalize(entry.getKey()).equals(area)) rules = entry.getValue();
        if (rules == null) return null;
        for (Rule rule : rules)
            if (rule.name.equalsIgnoreCase(monster.getName()))
                return rule.automaticIds.contains(monster.getId())
                    ? SlayerAssignmentLocation.Eligibility.ELIGIBLE : null;
        return SlayerAssignmentLocation.Eligibility.INELIGIBLE;
    }
}

package com.personalbis;

/**
 * Kurask/Turoth (leafy) damage eligibility.
 *
 * These targets still permit an accuracy roll to be calculated, but ordinary
 * damage is forced to zero unless the attack uses a leaf-bladed melee weapon,
 * broad ranged ammunition, or Magic Dart. This mirrors the Wiki calculator's
 * behaviour (e.g. Toktz-xil-ak can show accuracy against Kurask but max/DPS 0).
 */
public final class LeafyTargetRules
{
    private LeafyTargetRules() {}

    public static boolean restricted(MonsterDefinition monster)
    {
        return monster != null && monster.hasAttribute("leafy");
    }

    public static boolean meleeCanDamage(MonsterDefinition monster, EquipmentCandidate weapon)
    {
        if (!restricted(monster)) return true;
        if (weapon == null || weapon.getItem() == null || weapon.getItem().getName() == null) return false;
        String n=weapon.getItem().getName().toLowerCase();
        return n.contains("leaf-bladed spear") || n.contains("leaf-bladed sword") || n.contains("leaf-bladed battleaxe");
    }

    public static boolean rangedCanDamage(MonsterDefinition monster, EquipmentCandidate ammo)
    {
        if (!restricted(monster)) return true;
        if (ammo == null || ammo.getItem() == null || ammo.getItem().getName() == null) return false;
        String n=ammo.getItem().getName().toLowerCase();
        return n.contains("broad") && (n.contains("bolt") || n.contains("arrow"));
    }

    public static boolean magicCanDamage(MonsterDefinition monster, MagicSpell spell)
    {
        if (!restricted(monster)) return true;
        return spell != null && "Magic Dart".equalsIgnoreCase(spell.name);
    }

    /** Powered staves are not Magic Dart and therefore cannot damage leafy targets. */
    public static boolean poweredMagicCanDamage(MonsterDefinition monster)
    {
        return !restricted(monster);
    }
}

