 public String tier(){
  if(element().isEmpty())return "";
  String x=name.toLowerCase();
  if(x.endsWith(" strike"))return "strike";
  if(x.endsWith(" bolt"))return "bolt";
  if(x.endsWith(" blast"))return "blast";
  if(x.endsWith(" wave"))return "wave";
