/**
 * Personal BiS native bank view.
 *
 * The RuneLite bank search first restricts the bank to owned recommended items.
 * After the bank finishes building, the existing bank item widgets are reused
 * and laid out under OSRS-style section headers for each combat style.
 */
@Singleton
public class PersonalBisBankFilter
{
    private static final String TOKEN = "personalbis";
    private static final int ITEMS_PER_ROW = 8;
    private static final int ITEM_X_START = 51;
    private static final int ITEM_X_SPACING = 48;
    private static final int ITEM_Y_SPACING = 36;
    private static final int HEADER_HEIGHT = 20;
    private static final int DIVIDER_HEIGHT = 5;
    private static final int SECTION_GAP = 5;
    private static final int BANK_ITEM_WIDTH = 36;
    private static final int BANK_ITEM_HEIGHT = 32;
    private static final int HEADER_COLOR = new Color(228, 216, 162).getRGB();
    private static final int BEST_COLOR = new Color(80, 255, 80).getRGB();
    private static final int DIVIDER_COLOR = new Color(63, 54, 42).getRGB();

    private final Client client;
    private final ClientThread clientThread;
    private final BankSearch bankSearch;
    private final ItemManager itemManager;
    private final ItemExclusions exclusions;
    private final PersonalBisConfig config;
    private final Set<Widget> generatedWidgets = Collections.newSetFromMap(new java.util.IdentityHashMap<>());
    private final Set<Integer> recommendedItemIds = new HashSet<>();
    private final Map<AttackStyle, List<Integer>> recommendations = new EnumMap<>(AttackStyle.class);
    private final List<AttackStyle> styleOrder = new ArrayList<>();
    private final List<Widget> addedWidgets = new ArrayList<>();
    private final List<Widget> hiddenNativeDecorations = new ArrayList<>();
    private final List<RecommendedSupply> supplies = new ArrayList<>();
    private final List<RecommendedSupply> defenceReductionItems = new ArrayList<>();

    private final List<BankItem> groupItems = new ArrayList<>();
    private final Set<Widget> referenceWidgets = new HashSet<>();
    public void setGroupItems(List<BankItem> items)
    {
        groupItems.clear(); groupItems.addAll(items);
        if (active) clientThread.invokeLater(this::requestLayout);
    }
    private Widget lastLayoutContainer;
    private Widget sharedLayoutContainer;
    private final Map<Widget, int[]> sharedOriginalPositions = new java.util.IdentityHashMap<>();
    private int sharedOriginalScrollHeight;
    private final List<BankItem> personalItems = new ArrayList<>();
    public void setPersonalItems(List<BankItem> items) { personalItems.clear(); personalItems.addAll(items); }
    private boolean sharedOpen() {
        Widget w = client.getWidget(InterfaceID.SharedBank.ITEMS);
        return w != null && !w.isHidden();
    }
    private void requestLayout() {
        if (sharedOpen()) layoutSections(client.getWidget(InterfaceID.SharedBank.ITEMS));
        else bankSearch.layoutBank();
    }
    @Subscribe
    public void onGameTick(net.runelite.api.events.GameTick event) {
        if (active && sharedOpen()) layoutSections(client.getWidget(InterfaceID.SharedBank.ITEMS));
    }
    private boolean active;
    private AttackStyle bestStyle;
    private String targetHeader = "My BiS Finder";
    private int originalContainerChildren = -1;

    @Inject
    public PersonalBisBankFilter(Client client, ClientThread clientThread, BankSearch bankSearch, ItemManager itemManager, ItemExclusions exclusions, PersonalBisConfig config)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.bankSearch = bankSearch;
        this.itemManager = itemManager;
        this.exclusions = exclusions;
        this.config = config;
    }


    public void setRecommendations(Map<AttackStyle, List<Integer>> byStyle, List<AttackStyle> order, Set<Integer> allIds)
    {
        recommendations.clear();
        for (Map.Entry<AttackStyle, List<Integer>> entry : byStyle.entrySet())
        {
            recommendations.put(entry.getKey(), new ArrayList<>(entry.getValue()));
        }
        styleOrder.clear();
        styleOrder.addAll(order);
        recommendedItemIds.clear();
        recommendedItemIds.addAll(allIds);

        if (active)
        {
            clientThread.invokeLater(this::requestLayout);
        }
    }

    public void setBestStyle(AttackStyle style)
    {
        bestStyle = style;
        if (active) clientThread.invokeLater(this::requestLayout);
    }

    public void setTarget(MonsterDefinition monster)
    {
        targetHeader = SlayerTargetRequirements.bankHeader(monster);
        if (active) clientThread.invokeLater(this::requestLayout);
    }

    public void setSupplies(List<RecommendedSupply> items)
    {
        supplies.clear();
        if (items != null) supplies.addAll(items);
        for (RecommendedSupply item : supplies) recommendedItemIds.add(itemManager.canonicalize(item.itemId));
        if (active) clientThread.invokeLater(this::requestLayout);
    }

    public void setDefenceReductionItems(List<RecommendedSupply> items)
    {
        defenceReductionItems.clear();
        if(items!=null)defenceReductionItems.addAll(items);
        if(active)clientThread.invokeLater(this::requestLayout);
    }

    public boolean isActive()
    {
        return active;
    }

    public void refreshLayout()
    {
        if (active)
        {
            clientThread.invokeLater(this::requestLayout);
        }
    }

    public void toggle()
    {
        clientThread.invokeLater(() ->
        {
            if (active)
            {
                deactivateOnClientThread();
                return;
            }

            active = true;
            // Dedicated Personal BiS view: keep the complete native bank item set.
            // We only rearrange widgets after RuneLite finishes building the bank.
            requestLayout();
        });
    }

    public void deactivate()
    {
        clientThread.invokeLater(this::deactivateOnClientThread);
    }

    private void deactivateOnClientThread()
    {
        if (!active)
        {
            return;
        }
        active = false;
        clearAddedWidgets();
        restoreNativeDecorations();
        for (Map.Entry<Widget,int[]> entry : sharedOriginalPositions.entrySet()) {
            Widget w=entry.getKey(); int[] pos=entry.getValue();
            w.setOriginalX(pos[0]); w.setOriginalY(pos[1]); w.setHidden(pos[2] != 0); w.revalidate();
        }
        sharedOriginalPositions.clear();
        if(sharedLayoutContainer != null) { sharedLayoutContainer.setScrollHeight(sharedOriginalScrollHeight); sharedLayoutContainer.revalidate(); }
        sharedLayoutContainer=null;
        bankSearch.reset(true);
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if (!active || !"bankSearchFilter".equals(event.getEventName()))
        {
            return;
        }
        int[] intStack = client.getIntStack();
        int size = client.getIntStackSize();
        if (size < 2)
        {
            return;
        }
        // Personal BiS is a full-bank view, not a search filter. Keep every item.
        intStack[size - 2] = 1;
    }

    @Subscribe(priority = -1)
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (!active || event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
        {
            return;
        }

        Widget itemContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (itemContainer == null)
        {
            return;
        }

        // Finish the layout before another client cycle can build a menu from
        // the ordinary bank positions. A tick-end callback leaves a click window
        // and can also run after the planner has been deactivated.
        layoutSections(itemContainer);
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!active || !"Examine".equals(event.getOption())) return;
        Widget widget = event.getMenuEntry().getWidget();
        if (widget == null || !generatedWidgets.contains(widget) || widget.getItemId() <= 0) return;
        int itemId = widget.getItemId();
        client.getMenu().createMenuEntry(-1)
            .setOption(ItemExclusions.MENU_OPTION)
            .setTarget(event.getTarget())
            .setType(MenuAction.RUNELITE)
            .setDeprioritized(true)
            .onClick(entry -> exclusions.exclude(itemId));
    }

    @Subscribe(priority = -1)
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!active)
        {
            return;
        }

        Widget widget = event.getWidget();
        if (ItemExclusions.MENU_OPTION.equals(event.getMenuOption())
            && widget != null && referenceWidgets.contains(widget))
        {
            exclusions.exclude(widget.getItemId());
            event.consume();
            return;
        }
        if (isNativeBankNavigation(widget, event.getParam1()))
        {
            // Restore the ordinary bank before RuneLite/Jagex handles the same
            // tab or search click. Do not consume the event.
            deactivateOnClientThread();
            return;
        }

        if (widget != null && referenceWidgets.contains(widget)) { event.consume(); return; }
        boolean group = event.getParam1() == InterfaceID.SharedBank.ITEMS;
        if (group && "Examine".equals(event.getMenuOption())) return;
        if (event.getParam1() != InterfaceID.Bankmain.ITEMS && !group)
        {
            return;
        }

        // Examine and plugin-local actions do not withdraw or move bank items.
        if (event.getMenuAction() != MenuAction.CC_OP
            && event.getMenuAction() != MenuAction.CC_OP_LOW_PRIORITY)
        {
            return;
        }

        ItemContainer bank = client.getItemContainer(group ? InventoryID.INV_GROUP_TEMP : InventoryID.BANK);
        int slot = event.getParam0();
        int clickedItemId = event.getItemId();
        // Native widgets retain their real bank slot when moved. Never redirect a
        // stale click using the widget's current item (or a canonical alias).
        // A rebuild may have reused that widget for a different bank item.
        if (widget == null || widget.isHidden() || referenceWidgets.contains(widget)
            || bank == null || clickedItemId < 0
            || widget.getItemId() != clickedItemId
            || slot < 0 || slot >= bank.getItems().length
            || bank.getItems()[slot] == null
            || bank.getItems()[slot].getId() != clickedItemId)
        {
            event.consume();
        }
    }

    private boolean isNativeBankNavigation(Widget widget, int packedId)
    {
        if (isBankNavigationId(packedId)) return true;

        Widget current = widget;
        for (int depth = 0; current != null && depth < 5; depth++)
        {
            int parentId = current.getParentId();
            if (isBankNavigationId(current.getId()) || isBankNavigationId(parentId)) return true;
            current = parentId < 0 ? null : client.getWidget(parentId);
        }
        return false;
    }

    private static boolean isBankNavigationId(int id)
    {
        return id == InterfaceID.Bankmain.SEARCH
            || id == InterfaceID.Bankmain.SEARCH_GRAPHIC
            || id == InterfaceID.Bankmain.TABS
            || id == InterfaceID.SharedBank.SEARCH
            || id == InterfaceID.SharedBank.SEARCH_GRAPHIC
            || id == InterfaceID.SharedBank.MAIN_BANK;
    }

    private void layoutSections(Widget itemContainer)
    {
        clearAddedWidgets();
        lastLayoutContainer = itemContainer;
        boolean group = itemContainer.getId() == InterfaceID.SharedBank.ITEMS;
        if (group && sharedLayoutContainer != itemContainer) {
            sharedOriginalPositions.clear(); sharedLayoutContainer=itemContainer;
            sharedOriginalScrollHeight=itemContainer.getScrollHeight();
        }
        restoreNativeDecorations();

        Widget[] children = itemContainer.getDynamicChildren();
        if (children == null || children.length == 0)
        {
            return;
        }

        ItemContainer bank = client.getItemContainer(group ? InventoryID.INV_GROUP_TEMP : InventoryID.BANK);
        if (bank == null)
        {
            return;
        }

        // Preserve the native item widgets. Reuse each widget exactly once so withdraw
        // actions remain RuneLite/OSRS-native and do not require rebuilding on each click.
        List<Widget> itemWidgets = new ArrayList<>();
        for (Widget child : children)
        {
            if (child == null || referenceWidgets.contains(child)) continue;
            if (child.getItemId() >= 0)
            {
                if (group) sharedOriginalPositions.putIfAbsent(child, new int[]{child.getOriginalX(),child.getOriginalY(),child.isSelfHidden()?1:0});
                itemWidgets.add(child);
                child.setHidden(true);
            }
            else if (isNativeBankDivider(child))
            {
                // Default tab dividers retain their old absolute Y positions after we
                // rearrange native item widgets. Hide them in Personal BiS mode.
                child.setHidden(true);
                hiddenNativeDecorations.add(child);
            }
        }

        Map<Integer, Widget> ownedWidgets = new java.util.HashMap<>();
        Map<Integer, Widget> exactOwnedWidgets = new java.util.HashMap<>();
        for (Widget widget : itemWidgets)
        {
            Widget exactPrevious = exactOwnedWidgets.get(widget.getItemId());
            if (exactPrevious == null || (exactPrevious.getItemQuantity() <= 0 && widget.getItemQuantity() > 0))
                exactOwnedWidgets.put(widget.getItemId(), widget);
            int canonical = itemManager.canonicalize(widget.getItemId());
            Widget previous = ownedWidgets.get(canonical);
            if (previous == null || (previous.getItemQuantity() <= 0 && widget.getItemQuantity() > 0))
                ownedWidgets.put(canonical, widget);
        }

        Set<Widget> used = new HashSet<>();
        int y = 0;
        y = addHeader(itemContainer, targetHeader, y, true);

        // Reserve selected reduction stacks so they appear once below equipment.
        List<Widget> reductionWidgets=new ArrayList<>();
        for(RecommendedSupply item:defenceReductionItems){
            Widget widget=exactOwnedWidgets.get(item.itemId);
            if(widget!=null&&widget.getItemQuantity()>0&&!reductionWidgets.contains(widget))reductionWidgets.add(widget);
        }

        List<AttackStyle> order = styleOrder.isEmpty() ? Arrays.asList(AttackStyle.values()) : styleOrder;
        for (AttackStyle style : order)
        {
            List<Integer> ids = recommendations.get(style);
            if (ids == null || ids.isEmpty()) continue;

            y = addDivider(itemContainer, y);
            String title = displayStyle(style);
            if (style == bestStyle) title += "  <col=50ff50>Best style</col>";
            y = addHeader(itemContainer, title, y, style == bestStyle);

            int itemInSection = 0;
            for (Integer itemId : ids)
            {
                if (itemId == null) continue;
                Widget widget = ownedWidgets.get(itemManager.canonicalize(itemId));
                if(widget==null)
                {
                    // Some native placeholders have a different cache item ID
                    // that canonicalization does not map back to this equipment.
                    int placeholderId=client.getItemDefinition(itemId).getPlaceholderId();
                    if(placeholderId>0)widget=exactOwnedWidgets.get(placeholderId);
                }
                if (widget == null || used.contains(widget) || reductionWidgets.contains(widget)) continue;
                used.add(widget);
                generatedWidgets.add(widget);
                widget.setHidden(false);
                placeItem(widget, itemInSection++, y);
            }
            int rows = Math.max(1, (itemInSection + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW);
            y += rows * ITEM_Y_SPACING + SECTION_GAP;
        }

        if(!reductionWidgets.isEmpty()){
            y=addDivider(itemContainer,y);
            y=addHeader(itemContainer,"Defence reducing items",y,false);
            int index=0;
            for(Widget widget:reductionWidgets){
                used.add(widget);generatedWidgets.add(widget);widget.setHidden(false);
                placeItem(widget,index++,y);
            }
            y+=((index+ITEMS_PER_ROW-1)/ITEMS_PER_ROW)*ITEM_Y_SPACING+SECTION_GAP;
        }


        List<Widget> supplyWidgets=new ArrayList<>();
        for(RecommendedSupply supply:supplies){
            // Keep the exact supply/dose, including its genuine native placeholder
            // after the last item is withdrawn. Never create a withdrawable copy.
            Widget widget=exactOwnedWidgets.get(supply.itemId);
            if(widget==null)
            {
                int placeholderId=client.getItemDefinition(supply.itemId).getPlaceholderId();
                if(placeholderId>0)widget=exactOwnedWidgets.get(placeholderId);
            }
            if(widget!=null&&!used.contains(widget)&&!supplyWidgets.contains(widget))supplyWidgets.add(widget);
        }
        if(!supplyWidgets.isEmpty()){
            y=addDivider(itemContainer,y);
            y=addHeader(itemContainer,"Recommended",y,false);
            int index=0;
            for(Widget widget:supplyWidgets){
                used.add(widget);generatedWidgets.add(widget);widget.setHidden(false);
                placeItem(widget,index++,y);
            }
            y+=((index+ITEMS_PER_ROW-1)/ITEMS_PER_ROW)*ITEM_Y_SPACING+SECTION_GAP;
        }

        y = addDivider(itemContainer, y);
        java.util.Map<Integer, Integer> shared = new java.util.LinkedHashMap<>();
        for (List<Integer> ids : recommendations.values()) for (Integer id : ids)
        {
            if (id == null) continue;
            Widget local = ownedWidgets.get(itemManager.canonicalize(id));
            if (local != null && local.getItemQuantity() > 0) continue;
            for (BankItem item : (group ? personalItems : groupItems)) if (itemManager.canonicalize(item.getItemId()) == itemManager.canonicalize(id))
            { shared.put(item.getItemId(), 1); break; }
        }
        for (RecommendedSupply supply : supplies)
        {
            int missing = Math.max(0, supply.quantity - bank.count(supply.itemId));
            for (BankItem item : (group ? personalItems : groupItems)) if (item.getItemId() == supply.itemId && missing > 0)
            { shared.put(item.getItemId(), Math.min(missing, item.getQuantity())); break; }
        }
        if (!shared.isEmpty())
        {
            y = addHeader(itemContainer, group ? "Stored in personal bank" : "Stored in group storage", y, false);
            y = addHeader(itemContainer, group ? "Open personal bank to withdraw" : "Open group storage to withdraw", y, false);
            int index = 0;
            for (java.util.Map.Entry<Integer,Integer> entry : shared.entrySet())
            {
                Widget icon = itemContainer.createChild(-1, WidgetType.GRAPHIC);
                icon.setOriginalWidth(BANK_ITEM_WIDTH); icon.setOriginalHeight(BANK_ITEM_HEIGHT);
                icon.setBorderType(1); icon.setItemId(entry.getKey()); icon.setItemQuantity(entry.getValue());
                icon.setItemQuantityMode(ItemQuantityMode.ALWAYS);
                icon.setName(client.getItemDefinition(entry.getKey()).getName() + (group ? " (personal bank reference)" : " (group storage reference)"));
                icon.clearActions(); icon.setDragDeadTime(Integer.MAX_VALUE);
                final int referenceItemId = entry.getKey();
                icon.setAction(9, ItemExclusions.MENU_OPTION);
                icon.setHasListener(true);
                icon.setOnOpListener((net.runelite.api.widgets.JavaScriptCallback) event -> exclusions.exclude(referenceItemId));
                placeItem(icon, index++, y);
                addedWidgets.add(icon); referenceWidgets.add(icon);
            }
            y += ((index + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW) * ITEM_Y_SPACING + SECTION_GAP;
            y = addDivider(itemContainer, y);
        }
        if (!config.hideOtherBankItems())
        {
            y = addHeader(itemContainer, "Other items", y, false);
            int otherIndex = 0;
            for (Widget widget : itemWidgets)
            {
                if (used.contains(widget)) continue;
                widget.setHidden(false);
                placeItem(widget, otherIndex++, y);
            }
            int otherRows = (otherIndex + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW;
            y += otherRows * ITEM_Y_SPACING + SECTION_GAP;
        }

        itemContainer.setScrollHeight(Math.max(itemContainer.getHeight(), y + 10));
        itemContainer.revalidate();
        int scrollY = itemContainer.getScrollY();
        clientThread.invokeLater(() -> client.runScript(
            ScriptID.UPDATE_SCROLLBAR,
            group ? InterfaceID.SharedBank.SCROLLBAR : InterfaceID.Bankmain.SCROLLBAR,
            group ? InterfaceID.SharedBank.ITEMS : InterfaceID.Bankmain.ITEMS,
            scrollY));
    }

    private void configureBankItem(Widget widget, int itemId, int quantity)
    {
        int canonicalId = itemManager.canonicalize(itemId);
        ItemComposition normalDef = client.getItemDefinition(canonicalId);
        int displayId = canonicalId;
        boolean placeholder = quantity <= 0;

        if (placeholder)
        {
            int placeholderId = normalDef.getPlaceholderId();
            if (placeholderId > 0)
            {
                displayId = placeholderId;
            }
        }

        ItemComposition displayDef = client.getItemDefinition(displayId);
        widget.setOriginalWidth(BANK_ITEM_WIDTH);
        widget.setOriginalHeight(BANK_ITEM_HEIGHT);
        widget.setItemId(displayId);
        widget.setItemQuantity(Math.max(0, quantity));
        widget.setItemQuantityMode(placeholder ? ItemQuantityMode.NEVER : ItemQuantityMode.ALWAYS);
        widget.setOpacity(0);
        widget.setName("<col=ff9040>" + normalDef.getName() + "</col>");
        widget.setHidden(false);
        widget.setDragDeadTime(1000);
        widget.clearActions();
        if (placeholder)
        {
            widget.setAction(0, "Release");
        }
        else
        {
            widget.setAction(0, "Withdraw-1");
            widget.setAction(1, "Withdraw-5");
            widget.setAction(2, "Withdraw-10");
            widget.setAction(3, "Withdraw-X");
            widget.setAction(4, "Withdraw-All");
        }
        widget.setAction(10, "Examine");
        widget.revalidate();
    }

    private void placeItem(Widget widget, int itemIndex, int sectionY)
    {
        int x = ITEM_X_START + (itemIndex % ITEMS_PER_ROW) * ITEM_X_SPACING;
        int y = sectionY + (itemIndex / ITEMS_PER_ROW) * ITEM_Y_SPACING;
        widget.setOriginalX(x);
        widget.setOriginalY(y);
        widget.revalidate();
    }

    private int addHeader(Widget container, String text, int y, boolean best)
    {
        Widget label = container.createChild(-1, WidgetType.TEXT);
        label.setOriginalWidth(ITEMS_PER_ROW * ITEM_X_SPACING - ITEM_X_START);
        label.setOriginalHeight(16);
        // Align section headings with the first bank item rather than the bank container edge.
        label.setOriginalX(ITEM_X_START);
        label.setOriginalY(y + 2);
        label.setText(text);
        label.setFontId(FontID.PLAIN_11);
        label.setTextColor(best ? BEST_COLOR : HEADER_COLOR);
        label.setTextShadowed(true);
        label.revalidate();
        addedWidgets.add(label);
        return y + HEADER_HEIGHT;
    }

    private boolean isNativeBankDivider(Widget widget)
    {
        // Bank tab separators are thin, non-item graphical/rectangle children.
        // Restrict this deliberately so text, controls and native item widgets survive.
        return widget.getItemId() < 0
            && widget.getHeight() <= 3
            && widget.getWidth() >= 100;
    }

    private void restoreNativeDecorations()
    {
        for (Widget widget : hiddenNativeDecorations)
        {
            if (widget != null) widget.setHidden(false);
        }
        hiddenNativeDecorations.clear();
    }

    private int addDivider(Widget container, int y)
    {
        Widget line = container.createChild(-1, WidgetType.RECTANGLE);
        // Match the understated native bank-tab separator: one dark pixel,
        // spanning the same horizontal item area as the bank's own dividers.
        line.setOriginalX(ITEM_X_START);
        line.setOriginalY(y + 1);
        line.setOriginalWidth(ITEMS_PER_ROW * ITEM_X_SPACING - 4);
        line.setOriginalHeight(1);
        line.setTextColor(DIVIDER_COLOR);
        line.setFilled(true);
        line.setOpacity(0);
        line.revalidate();
        addedWidgets.add(line);
        return y + DIVIDER_HEIGHT;
    }

    private void clearAddedWidgets()
    {
        generatedWidgets.clear();
        if (addedWidgets.isEmpty())
        {
            return;
        }
        for (Widget widget : addedWidgets)
        {
            if (widget != null)
            {
                widget.setHidden(true);
            }
        }
        if (lastLayoutContainer != null) {
            Widget[] children=lastLayoutContainer.getChildren();
            if(children != null) {
                children=children.clone();
                for(int i=0;i<children.length;i++) if(addedWidgets.contains(children[i])) children[i]=null;
                int length=children.length; while(length>0 && children[length-1]==null) length--;
                lastLayoutContainer.setChildren(java.util.Arrays.copyOf(children,length));
            }
        }
        referenceWidgets.clear();
        addedWidgets.clear();
    }

    private String displayStyle(AttackStyle style)
    {
        switch (style)
        {
            case MELEE_STAB: return "Melee (Stab)";
            case MELEE_SLASH: return "Melee (Slash)";
            case MELEE_CRUSH: return "Melee (Crush)";
            case RANGED: return "Ranged";
            case MAGIC: return "Magic";
            default: return style.toString();
        }
    }
}

