import java.util.Set;
import java.util.HashSet;
import java.util.Locale;
import net.runelite.api.Skill;

/** Selected-target scaling, with all truncation stages kept explicit. */
final class RaidScaling
{
    private RaidScaling() {}
    private static boolean id(MonsterDefinition m, Integer... ids)
    {
        return m != null && Arrays.asList(ids).contains(m.getId());
    }
    static boolean isCox(MonsterDefinition m) { return m != null && m.hasAttribute("xerician"); }
    private static final Set<Integer> TOA = new HashSet<>(Arrays.asList(
        11789,11790,11791,11792,11793,11794,11795,11796,11797,11798,11799,
        11778,11779,11780,11719,11721,11724,11725,11726,11730,11732,11733,
        11751,11750,11752,11753,11754,11756,11757,11755,11758,11761,11763,11762,11764));
    static boolean isToa(MonsterDefinition m) { return m != null && TOA.contains(m.getId()); }
    private static boolean path(MonsterDefinition m)
    {
        return id(m,11789,11790,11791,11792,11793,11794,11795,11796,11797,11798,11799,
            11778,11779,11780,11719,11721,11724,11725,11726,11730,11732,11733);
    }
    private static boolean overlord(MonsterDefinition m) { int id=m.getId(); return id==11724||id==11725||id==11726; }
    static int invocation(MonsterDefinition m) { return value(m,"raid_level:"); }
    private static int value(MonsterDefinition m, String prefix)
    {
        if (m != null) for (String a : m.getAttributes()) if (a.startsWith(prefix)) return Integer.parseInt(a.substring(prefix.length()));
        return 0;
    }
    static int defenceRoll(MonsterDefinition m, int roll)
    {
        return isToa(m) && !overlord(m) ? (int)((long)roll * (250 + invocation(m)) / 250) : roll;
    }
    static int boosted(AccountSnapshot account, Skill skill, MonsterDefinition m)
    {
        int current = account.boosted(skill);
        if (!isToa(m) || !(skill == Skill.ATTACK || skill == Skill.STRENGTH || skill == Skill.RANGED || skill == Skill.MAGIC)) return current;
        int base = account.real(skill), salted = base + base * 16 / 100 + 11;
        if (m.hasAttribute("raid_assume_salts")) return Math.max(current, salted);
        if (m.hasAttribute("raid_exclude_salts"))
        {
            String prefix="raid_boost_"+skill.name()+":";
            for(String a:m.getAttributes()) if(a.startsWith(prefix)) return Integer.parseInt(a.substring(prefix.length()));
            return base;
        }
        return current;
    }

    static MonsterDefinition withOwnedBoosts(MonsterDefinition m, AccountSnapshot account, List<BankItem> owned)
    {
        if (!isToa(m) || !m.hasAttribute("raid_exclude_salts")) return m;
        List<String> attrs=new ArrayList<>(m.getAttributes());
        attrs.removeIf(a->a.startsWith("raid_boost_"));
        for(Skill skill:new Skill[]{Skill.ATTACK,Skill.STRENGTH,Skill.RANGED,Skill.MAGIC})
        {
            int level=account.real(skill),best=level;
            for(BankItem item:owned)
            {
                if(item.getQuantity()<=0)continue;
                String n=item.getName().toLowerCase(Locale.ROOT);
                int boost=0;
                if(skill==Skill.ATTACK){
                    if(n.startsWith("super attack(")||n.startsWith("super combat potion(")||n.startsWith("divine super attack potion(")||n.startsWith("divine super combat potion("))boost=5+level*15/100;
                    else if(n.startsWith("attack potion("))boost=3+level/10;
                }else if(skill==Skill.STRENGTH){
                    if(n.startsWith("super strength(")||n.startsWith("super combat potion(")||n.startsWith("divine super strength potion(")||n.startsWith("divine super combat potion("))boost=5+level*15/100;
                    else if(n.startsWith("strength potion("))boost=3+level/10;
                }else if(skill==Skill.RANGED){
                    if(n.startsWith("ranging potion(")||n.startsWith("divine ranging potion("))boost=4+level/10;
                }else{
                    if(n.equals("saturated heart"))boost=4+level*13/100;
                    else if(n.equals("imbued heart"))boost=1+level/10;
                    else if(n.startsWith("forgotten brew("))boost=3+level*8/100;
                    else if(n.startsWith("ancient brew("))boost=2+level*5/100;
                    else if(n.startsWith("magic potion(")||n.startsWith("divine magic potion("))boost=4;
                }
                best=Math.max(best,level+boost);
            }
            attrs.add("raid_boost_"+skill.name()+":"+best);
        }
        return new MonsterDefinition(m.getId(),m.getName(),m.getVersion(),m.getCombatLevel(),m.getDefenceLevel(),m.getMagicLevel(),m.getRangedLevel(),m.getHitpoints(),
            m.getStabDefence(),m.getSlashDefence(),m.getCrushDefence(),m.getMagicDefence(),m.getLightDefence(),m.getStandardDefence(),m.getHeavyDefence(),attrs,m.getSize(),m.getWeaknessElement(),m.getWeaknessSeverity(),m.getMagicAttack());
    }

    private static int scaleDrainOffensive(int base,RaidSettings s,boolean single)
    {
        if(single){int factor=Math.max(s.coxHp,55);if(s.challenge)factor=factor*150/100;return Math.max(1,base*factor/99);}
        int n=s.coxParty-1,highestHp=Math.max(55,Math.min(99,55+44*s.coxHp/99));
        int value=base*highestHp/99;value=value*(100+(int)Math.sqrt(n)*7+n)/100;
        if(s.challenge)value=value*150/100;return Math.max(50,Math.min(5000,value));
    }

    static MonsterDefinition apply(MonsterDefinition m, RaidSettings s)
    {
        if(FracturedArchiveRules.isTfa(m))return FracturedArchiveRules.scale(m,s.tfaParty);
        if (m == null || (!isCox(m) && !isToa(m))) return m;
        int hp=m.getHitpoints(), def=m.getDefenceLevel(), magic=m.getMagicLevel(), ranged=m.getRangedLevel();
        List<String> attrs = new ArrayList<>(m.getAttributes());
        attrs.removeIf(a -> a.startsWith("raid_level:") || a.equals("raid_assume_salts") || a.equals("raid_exclude_salts"));
        attrs.removeIf(a->a.startsWith("raid_options:"));
        attrs.add("raid_options:"+s.key(m));
        if (isToa(m))
        {
            boolean finalAkkha=m.getName().equals("Akkha")&&m.getVersion().startsWith("Final phase");
            if(finalAkkha)hp*=5;
            boolean core = id(m,11755,11758);
            if (core) hp=4500;
            hp += hp * ((core ? 1 : 4) * s.raidLevel / 10) / 100;
            if (path(m) && s.pathLevel > 0) hp=hp*(103+5*s.pathLevel)/100;
            if (s.toaParty >= 2)
            {
                int partyFactor=9*(s.toaParty>=3?2:1)+(s.toaParty>=4?6*(s.toaParty-3):0);
                hp=hp*(10+partyFactor)/10;
            }
            if (hp>100) { int round=hp>300?10:5; hp=(hp+round/2)/round*round; }
            if(finalAkkha)hp=Math.max(1,hp/5);
            attrs.add("raid_level:"+s.raidLevel);
            attrs.add(s.excludeSalts?"raid_exclude_salts":"raid_assume_salts");
        }
        else
        {
            if(WikiTargetEligibility.isGuardian(m))hp=151+s.coxMining;
            boolean magicDef=id(m,7559,7540,7543,7544,7545,7533,7530,7531,7532,7538,7539,7552,7555,7550,7553);
            boolean single=id(m,7548,7549,7538,7539);
            int baseDef=Math.max(def,magicDef?magic:1);
            int baseOff=Math.max(ranged,magicDef?1:magic);
            int off, defensive;
            if (single)
            {
                int h=Math.max(s.coxCombat,60),stat=Math.max(s.coxHp,55);
                if(s.challenge){h=h*150/100;stat=stat*150/100;}
                hp=Math.max(5,hp*h/126); off=Math.max(1,baseOff*stat/99); defensive=Math.max(1,baseDef*stat/99);
            }
            else
            {
                int n=s.coxParty-1, sqrt=(int)Math.sqrt(n), highestHp=Math.max(55,Math.min(99,55+44*s.coxHp/99));
                off=baseOff*highestHp/99; defensive=baseDef*highestHp/99; hp=hp*Math.max(60,s.coxCombat)/126;
                off=off*(100+sqrt*7+n)/100; defensive=defensive*(100+sqrt+n*7/10)/100;
                hp+=hp*(s.coxParty*50/100);
                if(s.challenge)
                {
                    off=off*150/100;
                    if(!id(m,7568)) hp=hp*150/100;
                    if(id(m,7540,7543,7544,7545)) defensive=defensive*(s.coxParty<4?120:135)/100;
                    else if(!id(m,7568)) defensive=defensive*150/100;
                }
                hp=Math.max(50,Math.min(30000,hp));off=Math.max(50,Math.min(5000,off));defensive=Math.max(50,Math.min(20000,defensive));
            }
            // BGS overflow passes through Strength/Attack before Magic. Preserve
            // the source-scaled offensive levels without adding incoming damage.
            int sourceAttack=DefenceReductionPlan.metadata(m,"npc_attack_level:");
            int sourceStrength=DefenceReductionPlan.metadata(m,"npc_strength_level:");
            int drainOff=scaleDrainOffensive(Math.max(baseOff,Math.max(sourceAttack,sourceStrength)),s,single);
            attrs.removeIf(a->a.startsWith("npc_attack_level:")||a.startsWith("npc_strength_level:"));
            if(sourceAttack>=0)attrs.add("npc_attack_level:"+(sourceAttack==1?1:drainOff));
            if(sourceStrength>=0)attrs.add("npc_strength_level:"+(sourceStrength==1?1:drainOff));
            if(def!=1) def=defensive;
            if(ranged!=1) ranged=off;
            if(magic!=1) magic=magicDef?defensive:off;
            if(id(m,7550,7551,7552,7553,7554,7555))
            {
                int factor=Math.min(s.coxParty-1,50)-3*(Math.min(s.coxParty,50)/8);
                hp=id(m,7550,7552,7553,7555)?600+300*factor:800+400*factor;
                if(id(m,7550,7553)) magic/=2;
            }
        }
        return new MonsterDefinition(m.getId(),m.getName(),m.getVersion(),m.getCombatLevel(),def,magic,ranged,hp,
            m.getStabDefence(),m.getSlashDefence(),m.getCrushDefence(),m.getMagicDefence(),m.getLightDefence(),
            m.getStandardDefence(),m.getHeavyDefence(),attrs,m.getSize(),m.getWeaknessElement(),m.getWeaknessSeverity(),m.getMagicAttack());
    }
}

package com.personalbis;

/** Immutable options captured before handing work to the optimizer thread. */
final class RaidSettings
{
    static final RaidSettings DEFAULT = new RaidSettings(99, 126, 1, false, 0, 0, 1, false);
    final int coxMining;
    final int tfaParty;
    final int coxHp, coxCombat, coxParty, raidLevel, pathLevel, toaParty;
    final boolean challenge, excludeSalts;

    RaidSettings(int hp, int combat, int party, boolean cm, int raid, int path, int toaSize, boolean exclude)
    {
        this(hp,combat,party,cm,raid,path,toaSize,exclude,99);
    }

    RaidSettings(int hp,int combat,int party,boolean cm,int raid,int path,int toaSize,boolean exclude,int mining)
    {
        this(hp,combat,party,cm,raid,path,toaSize,exclude,mining,2);
    }

    RaidSettings(int hp,int combat,int party,boolean cm,int raid,int path,int toaSize,boolean exclude,int mining,int tfaSize)
    {
        tfaParty=clamp(tfaSize,2,8);
        coxMining=clamp(mining,1,99);
        coxHp = clamp(hp, 1, 99); coxCombat = clamp(combat, 3, 126); coxParty = clamp(party, 1, 100);
        challenge = cm; raidLevel = clamp(raid, 0, 700); pathLevel = clamp(path, 0, 6);
        toaParty = clamp(toaSize, 1, 8); excludeSalts = exclude;
    }

    static final String CONFIG_KEY="raidSettings";

    String encode()
    {
        return "1|"+coxHp+'|'+coxCombat+'|'+coxParty+'|'+challenge+'|'+raidLevel+'|'+pathLevel+'|'+toaParty+'|'+excludeSalts+'|'+coxMining+'|'+tfaParty;
    }

    static RaidSettings decode(String value)
    {
        if(value==null)return DEFAULT;
        String[] fields=value.split("\\|",-1);
        if((fields.length!=10&&fields.length!=11)||!fields[0].equals("1"))return DEFAULT;
        if(!(fields[4].equals("true")||fields[4].equals("false"))
            ||!(fields[8].equals("true")||fields[8].equals("false")))return DEFAULT;
        try {
            return new RaidSettings(Integer.parseInt(fields[1]),Integer.parseInt(fields[2]),
                Integer.parseInt(fields[3]),Boolean.parseBoolean(fields[4]),Integer.parseInt(fields[5]),
                Integer.parseInt(fields[6]),Integer.parseInt(fields[7]),Boolean.parseBoolean(fields[8]),Integer.parseInt(fields[9]),fields.length==11?Integer.parseInt(fields[10]):2);
        } catch(NumberFormatException ex) { return DEFAULT; }
    }

    private static int clamp(int value, int low, int high) { return Math.max(low, Math.min(high, value)); }

    String key(MonsterDefinition m)
    {
        if(FracturedArchiveRules.isTfa(m))return "tfa:"+tfaParty;
        if (RaidScaling.isCox(m)) return "cox:" + coxHp + ':' + coxCombat + ':' + coxParty + ':' + challenge + ':' + coxMining;
        if (RaidScaling.isToa(m)) return "toa:" + raidLevel + ':' + pathLevel + ':' + toaParty + ':' + excludeSalts;
        return "";
    }
}

package com.personalbis;

import com.personalbis.wiki.WikiMonster;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

final class RaidTargetVariants
{
    private RaidTargetVariants() {}
    static boolean hidden(WikiMonster w)
    {
        return (w.id>=16678&&w.id<=16681) || w.id==16688 || (w.id==11763||w.id==11764) && "Invulnerable".equalsIgnoreCase(w.version);
    }
    static List<String> versions(WikiMonster w)
    {
        String v=w.version==null?"":w.version;
        if(w.attributes!=null&&w.attributes.contains("xerician"))
        {
            if(w.name.equals("Great Olm"))
            {
                if(w.id==7551||w.id==7554)return Collections.singletonList("Head");
                if(w.id==7552||w.id==7555)return Collections.singletonList("Left claw (Melee hand)");
                if(w.id==7550||w.id==7553)return Collections.singletonList("Right claw (Magic hand)");
            }
            return Collections.singletonList(v);
        }
        if(w.name.equals("Akkha"))return Arrays.asList("Magic-vulnerable phase","Ranged-vulnerable phase","Melee-vulnerable phase","Final phase (Melee only)");
        if(w.name.endsWith("' Warden"))
        {
            if(v.equals("Active"))return Arrays.asList("Phase 2 (Magic-vulnerable)","Phase 2 (Ranged-vulnerable)");
            if(v.equals("Core-ejected"))return Collections.singletonList("Phase 2 (Core-ejected)");
            if(v.equals("Damaged"))return Collections.singletonList("Phase 3");
            if(v.equals("Enraged"))return Collections.singletonList("Phase 3 (Enraged)");
        }
        if(w.name.equals("Obelisk (Tombs of Amascut)"))return Collections.singletonList("Phase 1");
        if(w.name.equals("Kephri")&&v.equals("Aggressive"))return Collections.singletonList("Unshielded");
        return TheatreOfBloodRules.versions(w.name,HueycoatlRules.part(w.id,v));
    }
    static int hp(WikiMonster w,String version)
    {
        return w.name.equals("Akkha")&&version.startsWith("Final phase")?Math.max(1,w.skills.hp/5):w.skills.hp;
    }
    static String key(MonsterDefinition m)
    {
        return RaidScaling.isCox(m)||RaidScaling.isToa(m)||FracturedArchiveRules.isTfa(m)?"|raid-state|"+m.getVersion().toLowerCase(Locale.ROOT):"";
    }
    static boolean canDamage(MonsterDefinition m,AttackStyle style)
    {
        if(m==null)return true;
        String v=m.getVersion();
        if(m.getName().equals("Akkha"))
        {
            if(v.startsWith("Magic-vulnerable"))return style==AttackStyle.MAGIC;
            if(v.startsWith("Ranged-vulnerable"))return style==AttackStyle.RANGED;
            if(v.startsWith("Melee-vulnerable")||v.startsWith("Final phase"))return style!=AttackStyle.MAGIC&&style!=AttackStyle.RANGED;
        }
        if(m.getName().endsWith("' Warden")&&v.startsWith("Phase 2 ("))
        {
            if(v.contains("Magic-vulnerable"))return style==AttackStyle.MAGIC;
            if(v.contains("Ranged-vulnerable"))return style==AttackStyle.RANGED;
        }
        return true;
    }
    static String note(MonsterDefinition m)
    {
        if(FracturedArchiveRules.isTfa(m))return FracturedArchiveRules.note(m);
        if(m!=null&&m.getName().endsWith("' Warden")&&m.getVersion().contains("Core-ejected"))
            return "Exposed core: melee attacks always deal their maximum damage. TTK assumes continuous exposure; ejection windows and body damage are not simulated.";
        if(m!=null&&m.getName().endsWith("' Warden")&&m.getVersion().contains("vulnerable"))
            return "Phase 2: attacks always hit; damage bounds depend on attack roll and scaled target defence.";
        return "";
    }
}

package com.personalbis;
/** Phase-1 weapon/ammunition compatibility and ranged defence classification. */
public final class RangedAmmoRules {
 private RangedAmmoRules(){}

 public static RangedAmmoType weaponAmmo(EquipmentCandidate w){
  if(w==null)return RangedAmmoType.NONE;
  String n=name(w), c=w.getWeaponCategory().toLowerCase();
  if(n.contains("bow of faerdhinen")||n.contains("crystal bow")||n.contains("twisted bow")&&false)return RangedAmmoType.INTERNAL;
  if(n.contains("blowpipe"))return RangedAmmoType.DART;
  if(c.contains("crossbow")||n.contains("crossbow"))return RangedAmmoType.BOLT;
  if(c.equals("bow")||n.endsWith(" bow")||n.contains("shortbow")||n.contains("longbow")||n.contains("twisted bow"))return RangedAmmoType.ARROW;
  if(c.contains("thrown")||n.contains("knife")||n.contains("javelin")||n.contains("thrownaxe"))return RangedAmmoType.INTERNAL;
  return RangedAmmoType.NONE;
 }

 public static RangedAmmoType ammoType(EquipmentCandidate a){
  if(a==null)return RangedAmmoType.NONE; String n=name(a);
  if(n.contains("arrow"))return RangedAmmoType.ARROW;
  if(n.contains("bolt")&&!n.contains("bolt pouch"))return RangedAmmoType.BOLT;
  if(n.contains("dart"))return RangedAmmoType.DART;
  return RangedAmmoType.NONE;
 }

 public static boolean compatible(EquipmentCandidate w,EquipmentCandidate a){
  // Blowpipe darts are stored inside the weapon rather than equipped in the
  // ammo slot. The Wiki equipment table therefore reports no equipped-ammo
  // applicability; production optimisation must still pair the weapon with
  // an owned dart so its Ranged Strength is included.
  if(w!=null&&name(w).equals("ascension crossbows"))return a!=null&&ArraysContainsAscension(a.getItem().getItemId());
  if(a!=null&&name(a).contains("ascension bolt"))return false;
  if(usesLoadedDarts(w))return a!=null&&ammoType(a)==RangedAmmoType.DART;
  if(w!=null){ WikiEquipmentEngine.AmmoApplicability wa=WikiEquipmentEngine.ammoApplicability(w.getItem().getItemId(),a==null?null:a.getItem().getItemId()); if(wa==WikiEquipmentEngine.AmmoApplicability.INVALID)return false; if(wa==WikiEquipmentEngine.AmmoApplicability.INCLUDED)return true; }
  RangedAmmoType need=weaponAmmo(w);
  if(need==RangedAmmoType.NONE||need==RangedAmmoType.INTERNAL)return a==null;
  if(a==null||ammoType(a)!=need)return false;
  return tierCompatible(w,a);
 }
 private static boolean tierCompatible(EquipmentCandidate w,EquipmentCandidate a){
  String wn=name(w), an=name(a);

  // Dedicated ammunition families must be resolved before the generic metal-bolt
  // progression. Their names contain "bolt", but they are not interchangeable.
  if(isHuntersSunlightCrossbow(wn))
   return an.contains("sunlight antler bolt")||an.contains("moonlight antler bolt");
  if(isHuntersCrossbow(wn))
   return an.contains("kebbit bolt")||an.contains("long kebbit bolt");
  if(wn.contains("karil")&&wn.contains("crossbow"))return an.contains("bolt rack");
  if(wn.contains("dorgeshuun crossbow"))return an.contains("bone bolt");
  if(wn.contains("ballista"))return an.contains("javelin");

  // Special-family ammunition must never leak into ordinary crossbows.
  if(an.contains("kebbit bolt")||an.contains("antler bolt")||an.contains("bolt rack")||an.contains("bone bolt"))
   return false;

  if(weaponAmmo(w)==RangedAmmoType.ARROW){
   int cap=arrowCap(wn), tier=arrowTier(an); return tier==0||cap==0||tier<=cap;
  }
  if(weaponAmmo(w)==RangedAmmoType.BOLT){
   // Crossbow families have many special exceptions; enforce the common metal progression.
   int cap=boltCap(wn), tier=boltTier(an); return tier==0||cap==0||tier<=cap;
  }
  return true;
 }
 private static boolean ArraysContainsAscension(int id){return id==34684||id==34690||id==34696||id==34702||id==34708;}
 private static boolean isHuntersSunlightCrossbow(String n){
  return n.contains("hunter")&&n.contains("sunlight")&&n.contains("crossbow");
 }
 private static boolean isHuntersCrossbow(String n){
  return n.contains("hunter")&&n.contains("crossbow")&&!n.contains("sunlight")&&!n.contains("dragon hunter");
 }
 private static int arrowTier(String n){
  if(n.contains("dragon arrow"))return 7;if(n.contains("amethyst arrow"))return 6;if(n.contains("rune arrow"))return 5;
  if(n.contains("adamant arrow"))return 4;if(n.contains("mithril arrow"))return 3;if(n.contains("steel arrow"))return 2;if(n.contains("iron arrow"))return 1;return 0;
 }
 private static int arrowCap(String n){
  if(n.contains("twisted bow")||n.contains("dark bow"))return 7;if(n.contains("magic")||n.contains("seercull"))return 5;
  if(n.contains("yew"))return 5;if(n.contains("maple"))return 4;if(n.contains("willow"))return 3;if(n.contains("oak"))return 2;if(n.contains("shortbow")||n.contains("longbow"))return 1;return 0;
 }
 private static int boltTier(String n){
  if(n.contains("dragon bolt")||n.contains("dragon bolts"))return 7;
  if(n.contains("runite bolt")||n.contains("rune bolt")||n.contains("dragonstone bolt")||n.contains("onyx bolt"))return 6;
  if(n.contains("adamant bolt")||n.contains("ruby bolt")||n.contains("diamond bolt"))return 5;
  if(n.contains("mithril bolt")||n.contains("sapphire bolt")||n.contains("emerald bolt"))return 4;
  if(n.contains("steel bolt")||n.contains("red topaz bolt"))return 3;
  if(n.contains("iron bolt")||n.contains("pearl bolt"))return 2;
  if(n.contains("bronze bolt")||n.contains("opal bolt"))return 1;
  return 0;
 }
 private static int boltCap(String n){
  if(n.contains("dragon hunter crossbow")||n.contains("dragon crossbow")||n.contains("zaryte crossbow"))return 7;
  if(n.contains("rune crossbow"))return 6;if(n.contains("adamant crossbow"))return 5;if(n.contains("mithril crossbow"))return 4;
  if(n.contains("steel crossbow"))return 3;if(n.contains("iron crossbow"))return 2;if(n.contains("bronze crossbow"))return 1;return 0;
 }

 public enum DefenceClass { LIGHT, STANDARD, HEAVY }

 public static DefenceClass defenceClass(EquipmentCandidate w){
  if(w==null)return DefenceClass.STANDARD;
  if(name(w).equals("ascension crossbows"))return DefenceClass.HEAVY;
  String n=name(w), c=w.getWeaponCategory().toLowerCase();
  // Light: arrows, darts, knives and blowpipe-like rapid projectiles.
  if(weaponAmmo(w)==RangedAmmoType.ARROW || weaponAmmo(w)==RangedAmmoType.DART ||
     n.contains("knife") || n.contains("dart") || n.contains("blowpipe"))
   return DefenceClass.LIGHT;
  // Heavy projectile families. Keep crossbows STANDARD: bolts use standard defence.
  if(n.contains("ballista") || n.contains("javelin") || n.contains("thrownaxe") ||
     c.contains("ballista"))
   return DefenceClass.HEAVY;
  return DefenceClass.STANDARD;
 }

 public static int targetDefence(MonsterDefinition m,EquipmentCandidate w){
  if(m==null)return 0;
  switch(defenceClass(w)){
   case LIGHT:return m.getLightDefence();
   case HEAVY:return m.getHeavyDefence();
   default:return m.getStandardDefence();
  }
 }

 /** True when the equipped ammo slot is reserved for ammunition. */
 public static boolean requiresEquippedAmmo(EquipmentCandidate w){
  RangedAmmoType t=weaponAmmo(w);
  return t==RangedAmmoType.ARROW||t==RangedAmmoType.BOLT;
 }

 /** True when the ammo equipment slot is free for a blessing/neutral item. */
 public static boolean ammoSlotFreeForNeutralGear(EquipmentCandidate w){
  return !requiresEquippedAmmo(w);
 }

 public static boolean usesLoadedDarts(EquipmentCandidate w){return w!=null&&name(w).contains("blowpipe");}

 /** Defensive guard for mandatory-shield targets when upstream item metadata is incomplete. */
 public static boolean occupiesBothHands(EquipmentCandidate w){
  if(w==null)return false;
  String n=name(w);
  // Rune crossbows are one-handed. Keep this authoritative override ahead of
  // imported metadata so mandatory shields remain eligible after data refreshes.
  if(n.equals("rune crossbow")||n.startsWith("rune crossbow ("))return false;
  return w.isTwoHanded()||n.contains("blowpipe")
    ||((n.endsWith(" bow")||n.contains("shortbow")||n.contains("longbow")||n.contains("twisted bow"))
       &&!n.contains("crossbow"));
 }

 public static boolean usesExternalAmmo(EquipmentCandidate w){
  return requiresEquippedAmmo(w);
 }
 private static String name(EquipmentCandidate c){return c.getItem().getName().toLowerCase();}
}

package com.personalbis;
import java.util.Map;
import java.util.HashMap;
import javax.inject.Inject;
import net.runelite.api.Skill;
public class RangedCombatCalculator {
 private final AccountSnapshot account;
 @Inject public RangedCombatCalculator(AccountSnapshot a){account=a;}
 public RangedCombatResult calculate(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task){
  RangedCombatResult best=null;
  for(RangedStance st:RangedStance.values())for(RangedPrayer p:prayers()){
   EquipmentCandidate weapon=gear.get(EquipmentSlot.WEAPON);
   if(weapon!=null&&"Salamander".equalsIgnoreCase(weapon.getWeaponCategory())&&st!=RangedStance.RAPID)continue;
   RangedCombatResult r=calculate(gear,m,task,st,p); if(best==null||FinalLoadoutSelection.betterTtk(r.getExpectedTtkSeconds(),r.getDps(),best.getExpectedTtkSeconds(),best.getDps()))best=r;
  } return best;
 }
 public RangedCombatResult calculate(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task,RangedStance st,RangedPrayer p){
  return calculateInternal(gear,m,task,st,p,true);
 }
 RangedCombatResult calculateSnapshot(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task,RangedStance st,RangedPrayer p){
  return calculateInternal(gear,m,task,st,p,false);
 }
 private RangedCombatResult calculateInternal(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task,RangedStance st,RangedPrayer p,boolean finiteFight){
  int atk=0,str=0,speed=4; boolean slayer=false; EquipmentCandidate weapon=gear.get(EquipmentSlot.WEAPON);
  for(EquipmentCandidate c:gear.values()){if(c==null)continue;
   if(c.getSlot()==EquipmentSlot.AMMO && !RangedAmmoRules.compatible(weapon,c)) continue;
   atk+=c.getRangedAttack();str+=c.getRangedStrength();
   if(c.getSlot()==EquipmentSlot.WEAPON&&c.getAttackSpeed()>0)speed=c.getAttackSpeed();
   String n=c.getItem().getName().toLowerCase(); if(c.getSlot()==EquipmentSlot.HEAD&&(n.contains("slayer helm")||n.contains("slayer helmet")||n.contains("black mask"))&&(n.contains("(i)")||n.contains("imbued")))slayer=true;}
  // transform(str, rangedStr, magicAttack, magicDamage, rangedAttack): ranged
  // strength must occupy the second numeric channel. Passing it as melee Str
  // zeroed every weapon/ammo Ranged Strength during the exact final evaluation.
  WikiEquipmentEngine.Totals wikiEq=WikiEquipmentEngine.transform(gear,m,null,0,str,0,0.0,atk); atk=wikiEq.rangedAttack; str=wikiEq.rangedStr;
  int level=Math.max(1,RaidScaling.boosted(account,Skill.RANGED,m));
  boolean voidRanged=RangedLoadoutEffects.voidRanged(gear), eliteVoid=RangedLoadoutEffects.eliteVoidRanged(gear);
  int eff=CombatEffectiveLevels.ranged(level,p.getRanged(),st.getRangedBoost(),voidRanged);
  boolean salve=RangedLoadoutEffects.rangedSalveActive(gear,m);
  int roll=eff*(atk+64);
  roll=(int)Math.floor(roll*RangedLoadoutEffects.crystalAccuracy(gear,weapon));
  roll=WikiRangedEffects.accuracyAfterExclusive(roll,gear.values(),m,task,slayer);
  roll=WikiRangedEffects.postAccuracy(roll,weapon,m,st,4);
  if(RaidCombatRules.wardenP2(m)&&RangedWeaponEffects.isTwistedBow(weapon))
   roll=RangedWeaponEffects.scaleTwisted(roll,m,true);
  int def=m==null?1:Math.max(0,VardorvisRules.startingDefence(m)), bonus=RangedAmmoRules.targetDefence(m,weapon);
  int defRoll=RaidScaling.defenceRoll(m,(def+9)*(bonus+64));
  double acc=WikiPlayerVsNpcCalc.targetAccuracy(m,FracturedArchiveRules.imp(m)?1.0:WikiAccuracyRoll.normal(roll,defRoll));
  boolean strengthRanged=EquipmentSetRules.strengthRanged(weapon);
  int damageLevel=strengthRanged?Math.max(1,RaidScaling.boosted(account,Skill.STRENGTH,m)):level;
  if(strengthRanged){str=0;for(EquipmentCandidate c:gear.values())if(c!=null){
   com.personalbis.wiki.WikiEquipment item=WikiEquipmentEngine.canonicalItem(c.getItem().getItemId());
   str+=item!=null&&item.bonuses!=null?item.bonuses.str:c.getStrengthBonus();}}
  int dmgEff=CombatEffectiveLevels.rangedDamage(damageLevel,p.getRangedStrength(),st.getRangedBoost(),voidRanged,eliteVoid);
  int max=WikiIntegerStages.maxHitFromEffective(dmgEff,str+64);
  max=(int)Math.floor(max*RangedLoadoutEffects.crystalDamage(gear,weapon));
  max=strengthRanged?EquipmentSetRules.strengthRangedMax(max,gear,m,task):WikiRangedEffects.damageAfterExclusive(max,gear.values(),m,weapon,task,slayer);
  max=WikiRangedEffects.postDamage(max,weapon,m,task,slayer);
  // Wiki parity: Bone shortbow receives the ratbane flat +10 max hit on rat targets.
  max += MeleeWeaponEffects.ratbaneBonusMax(weapon,m);
  int baseSpeed=WikiAttackSpeedRules.attackTicks(Math.max(1,speed+st.getSpeedDelta()),weapon,m);
  // Unshielded Tormented Demons take ticks^2-16 bonus damage from heavy ranged and are hit a tick faster.
  boolean tdBonus=TormentedDemonRules.unshieldedBonusApplies(m,AttackStyle.RANGED,weapon,false);
  int actualSpeed=tdBonus?baseSpeed-1:baseSpeed;
  int preSpecMax=max;
  int normalMin=0;
  if(RaidCombatRules.wardenP2(m)){int[] bounds=RaidCombatRules.wardenBounds(max,roll,defRoll);normalMin=bounds[0];max=bounds[1];acc=1.0;}
  EquipmentCandidate ammo=gear.get(EquipmentSlot.AMMO);
  HitDistribution.AttackDistribution rangedDist=WikiPlayerVsNpcCalc.finalDistribution(
      WikiPlayerVsNpcCalc.rangedAttacker(weapon,ammo,m,level,normalMin,max,acc,account.isKandarinHardCompleted(),gear.values()),
      m,AttackStyle.RANGED,weapon,null,false,gear.values());
  if(tdBonus)rangedDist=TormentedDemonRules.withUnshieldedBonus(rangedDist,baseSpeed);
  final int normalMax=max;
  double expectedDamage=WikiPlayerVsNpcCalc.expectedDamage(rangedDist);
  double dps=WikiPlayerVsNpcCalc.dps(rangedDist,actualSpeed);
  int targetHp=m==null?1:Math.max(1,m.getHitpoints());
  boolean ruby=ammo!=null&&ammo.getItem()!=null&&ammo.getItem().getName().toLowerCase().contains("ruby");
  Map<Integer,HitDistribution.AttackDistribution> hpDists=ruby?new HashMap<>():null;
  HitDistribution rubyBase=ruby?WikiPlayerVsNpcCalc.rangedRubyBaseDistribution(
      m,level,normalMin,normalMax,acc,account.isKandarinHardCompleted()):null;
  double ttk=!finiteFight||VardorvisRules.supported(m)?Double.POSITIVE_INFINITY:ruby
      ?ExpectedKillTime.seconds(targetHp,actualSpeed,hp->hpDists.computeIfAbsent(EnchantedBoltEffects.rubyHpBucket(hp),key->
          tdBonus?TormentedDemonRules.withUnshieldedBonus(WikiPlayerVsNpcCalc.rangedRubyFinalDistributionAtHp(rubyBase,weapon,ammo,m,
              account.isKandarinHardCompleted(),key),baseSpeed):WikiPlayerVsNpcCalc.rangedRubyFinalDistributionAtHp(rubyBase,weapon,ammo,m,
              account.isKandarinHardCompleted(),key)))
      :ExpectedKillTime.seconds(rangedDist,targetHp,actualSpeed);
  if(finiteFight&&VardorvisRules.supported(m)){
   final int fixedRoll=roll, fixedMin=normalMin, fixedMax=normalMax;
   Map<String,HitDistribution.AttackDistribution> evolving=new HashMap<>();
   ttk=ExpectedKillTime.seconds(targetHp,actualSpeed,hp->{
    int defence=VardorvisRules.defence(m,hp);
    int rubyHp=ruby?EnchantedBoltEffects.rubyHpBucket(hp):targetHp;
    String key=defence+":"+rubyHp;
    return evolving.computeIfAbsent(key,k->{
     double chance=WikiAccuracyRoll.normal(fixedRoll,(defence+9)*(bonus+64));
     if(ruby){
      HitDistribution base=WikiPlayerVsNpcCalc.rangedRubyBaseDistribution(m,level,fixedMin,fixedMax,chance,account.isKandarinHardCompleted());
      return WikiPlayerVsNpcCalc.rangedRubyFinalDistributionAtHp(base,weapon,ammo,m,account.isKandarinHardCompleted(),rubyHp);
     }
     return WikiPlayerVsNpcCalc.finalDistribution(
      WikiPlayerVsNpcCalc.rangedAttacker(weapon,ammo,m,level,fixedMin,fixedMax,chance,account.isKandarinHardCompleted(),gear.values()),
      m,AttackStyle.RANGED,weapon,null,false,gear.values());
    });
   });
  }
  max=rangedDist.max();
  if(!WikiTargetEligibility.rangedCanDamage(m) || !LeafyTargetRules.rangedCanDamage(m,ammo) || !MeleeWeaponEffects.ratBoneCanDamage(weapon,m)){max=0;dps=0.0;ttk=Double.POSITIVE_INFINITY;}
  if(FracturedArchiveRules.blade(m))ttk=Double.POSITIVE_INFINITY;
  return new RangedCombatResult(dps,ttk,acc,max,roll,defRoll,atk,str,actualSpeed,eff,dmgEff,st,p,preSpecMax);
 }
 private RangedPrayer[] prayers(){int x=account.real(Skill.PRAYER);
  if(x>=74 && account.isRigourUnlocked())return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.RIGOUR};
  if(x>=62 && account.isDeadeyeUnlocked())return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.DEADEYE};
  if(x>=44)return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.EAGLE_EYE};
  if(x>=26)return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.HAWK_EYE};
  if(x>=8)return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.SHARP_EYE};
  return new RangedPrayer[]{RangedPrayer.NONE};}
}

