package com.personalbis;

import java.util.Locale;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/** Small authoritative guard for Slayer-only targets and their mandatory tools. */
public final class SlayerTargetRequirements {
    private SlayerTargetRequirements() {}

    public static int requiredLevel(MonsterDefinition monster) {
        if (monster == null) return 0;
        String n = monster.getName().toLowerCase(Locale.ROOT);
        if (n.contains("hydra")) return 95;
        if (n.contains("cerberus")) return 91;
        if (n.contains("abyssal sire")) return 85;
        if (n.contains("gargoyle") || n.equals("dawn") || n.equals("dusk")) return 75;
        if (n.contains("smoke devil")) return 93;
        if (n.contains("basilisk knight")) return 60;
        if (n.contains("basilisk")) return 40;
        if (n.contains("rockslug")) return 20;
        if (n.contains("zygomite")) return 57;
        if (n.contains("dust devil")) return 65;
        if (n.contains("nechryael")) return 80;
        if (n.contains("kraken")) return 87;
        if (n.contains("abyssal demon")) return 85;
        return 0;
    }

    public static String requiredItem(MonsterDefinition monster) {
        if (monster == null) return "";
        String n = monster.getName().toLowerCase(Locale.ROOT);
        if (n.contains("gargoyle")) return "Rock hammer or equivalent finishing hammer";
        if (isDesertLizard(n)) return "Ice cooler";
        if (n.contains("zygomite")) return "Fungicide spray";
        if (n.contains("rockslug")) return "Bag of salt or Brine sabre";
        if (n.contains("mogre")) return "Fishing explosive (to lure)";
        if (n.contains("molanisk")) return "Slayer bell (to lure)";
        if (n.contains("basilisk knight")) return "Mirror shield or V's shield";
        if (n.contains("basilisk")) return "Mirror shield or V's shield";
        if (n.contains("cockatrice")) return "Mirror shield or V's shield";
        if (n.contains("banshee")) return "Earmuffs, masked earmuffs or Slayer helmet";
        if (n.contains("dust devil") || n.contains("smoke devil")) return "Face mask or Slayer helmet";
        if (n.contains("aberrant spectre")) return "Nose peg or Slayer helmet";
        if (n.contains("wall beast")) return "Spiny helmet or Slayer helmet";
        if (n.contains("cave horror")) return "Witchwood icon";
        if (n.contains("killerwatt")) return "Insulated boots";
        if (n.contains("fever spider")) return "Slayer gloves";
        if (n.contains("harpie bug swarm")) return "Lit bug lantern";
        if (n.contains("turoth") || n.contains("kurask"))
            return "Leaf-bladed weapon, broad ammunition or Magic Dart";
        return "";
    }

    /** Equipment that must remain equipped for the target's attacks to be viable. */
    public static EquipmentSlot requiredEquipmentSlot(MonsterDefinition monster) {
        String n = monster == null ? "" : monster.getName().toLowerCase(Locale.ROOT);
        if (n.contains("basilisk") || n.contains("cockatrice") || n.contains("harpie bug swarm")) return EquipmentSlot.SHIELD;
        if (n.contains("banshee") || n.contains("dust devil") || n.contains("smoke devil") || n.contains("aberrant spectre") || n.contains("wall beast")) return EquipmentSlot.HEAD;
        if (n.contains("cave horror")) return EquipmentSlot.NECK;
        if (n.contains("killerwatt")) return EquipmentSlot.FEET;
        if (n.contains("fever spider")) return EquipmentSlot.HANDS;
        return null;
    }

    public static boolean validRequiredEquipment(MonsterDefinition monster, EquipmentCandidate candidate) {
        EquipmentSlot slot = requiredEquipmentSlot(monster);
        if (slot == null) return true;
        if (candidate == null || candidate.getSlot() != slot || candidate.getItem() == null) return false;
        String n = candidate.getItem().getName().toLowerCase(Locale.ROOT);
        String target = monster.getName().toLowerCase(Locale.ROOT);
        if (target.contains("basilisk") || target.contains("cockatrice"))
            return n.contains("mirror shield") || n.equals("v's shield");
        if (target.contains("harpie bug swarm")) return n.contains("lit bug lantern");
        if (target.contains("banshee")) return n.contains("earmuffs") || n.contains("slayer helmet");
        if (target.contains("dust devil") || target.contains("smoke devil")) return n.contains("face mask") || n.contains("facemask") || n.contains("slayer helmet");
        if (target.contains("aberrant spectre")) return n.contains("nose peg") || n.contains("slayer helmet");
        if (target.contains("wall beast")) return n.contains("spiny helmet") || n.contains("slayer helmet");
        if (target.contains("cave horror")) return n.contains("witchwood icon");
        if (target.contains("killerwatt")) return n.contains("insulated boots");
        if (target.contains("fever spider")) return n.contains("slayer gloves");
        return false;
    }

    /** Inventory-use finishing/luring tools, in preferred fallback order. */
    public static String[] finishingItems(MonsterDefinition monster) {
        String n = monster == null ? "" : monster.getName().toLowerCase(Locale.ROOT);
        if (n.contains("gargoyle")) return new String[]{"Rock hammer", "Rock thrownhammer", "Granite hammer"};
        if (isDesertLizard(n)) return new String[]{"Ice cooler"};
        if (n.contains("zygomite")) return new String[]{"Fungicide spray"};
        if (n.contains("rockslug")) return new String[]{"Bag of salt", "Brine sabre"};
        if (n.contains("mogre")) return new String[]{"Fishing explosive"};
        if (n.contains("molanisk")) return new String[]{"Slayer bell"};
        return new String[0];
    }

    private static boolean isDesertLizard(String name) {
        return name.equals("lizard") || name.contains("small lizard") || name.contains("desert lizard");
    }

    public static EquipmentCandidate firstRequiredEquipment(MonsterDefinition monster,
        java.util.List<EquipmentCandidate> candidates) {
        if (requiredEquipmentSlot(monster) == null) return null;
        String target=monster.getName().toLowerCase(Locale.ROOT);
        if ((target.contains("basilisk") || target.contains("cockatrice")) && candidates != null)
            for (EquipmentCandidate candidate : candidates)
                if (candidate != null && !candidate.getRequirementResult().isBlocked()
                    && candidate.getItem()!=null
                    && candidate.getItem().getName().equalsIgnoreCase("V's shield")) return candidate;
        if (candidates != null) for (EquipmentCandidate candidate : candidates)
            if (candidate != null && !candidate.getRequirementResult().isBlocked()
                && validRequiredEquipment(monster, candidate)) return candidate;
        return null;
    }

    /**
     * Reserve a mandatory slot. When the player owns a valid item it is the only
     * candidate for that slot; otherwise the empty list deliberately leaves the
     * slot blank while allowing the rest of the loadout to be calculated.
     */
    public static Map<EquipmentSlot,List<EquipmentCandidate>> constrainRanked(
        MonsterDefinition monster, Map<EquipmentSlot,List<EquipmentCandidate>> ranked) {
        Map<EquipmentSlot,List<EquipmentCandidate>> constrained=new EnumMap<>(EquipmentSlot.class);
        if(ranked!=null)for(Map.Entry<EquipmentSlot,List<EquipmentCandidate>> entry:ranked.entrySet())
            constrained.put(entry.getKey(),entry.getValue()==null?new ArrayList<>():new ArrayList<>(entry.getValue()));
        EquipmentSlot slot=requiredEquipmentSlot(monster);
        if(slot!=null){
            EquipmentCandidate required=firstRequiredEquipment(monster,constrained.get(slot));
            constrained.put(slot,required==null?new ArrayList<>():new ArrayList<>(java.util.Collections.singletonList(required)));
        }
        return constrained;
    }

    public static boolean allowed(MonsterDefinition monster, int slayerLevel) {
        return requiredLevel(monster) <= 0 || slayerLevel >= requiredLevel(monster);
    }

    public static String bankHeader(MonsterDefinition monster) {
        if (monster == null) return "My BiS Finder";
        String header = monster.getName() + (monster.getVersion().isEmpty() ? "" : " [" + monster.getVersion() + "]");
        String requirement = requiredItem(monster);
        return requirement.isEmpty() ? header : header + " — Requires " + requirement;
    }

    /** Target families found at one or more Slayer-ring teleport destinations. */
    public static boolean slayerRingTeleportUseful(MonsterDefinition monster) {
        if (monster == null) return false;
        String n = monster.getName().toLowerCase(Locale.ROOT);
        String[] families = {
            // Slayer Tower
            "crawling hand", "banshee", "infernal mage", "bloodveld", "aberrant spectre",
            "gargoyle", "nechryael", "abyssal demon",
            // Fremennik Slayer Dungeon
            "cave crawler", "rockslug", "cockatrice", "pyrefiend", "basilisk", "jelly",
            "turoth", "kurask",
            // Stronghold Slayer Cave
            "ankou", "blue dragon", "brine rat", "fire giant", "greater demon", "hellhound",
            // Tarn's Lair and Mourner tunnels
            "terror dog", "dark beast"
        };
        for (String family : families) if (n.contains(family)) return true;
        return false;
    }
}

package com.personalbis;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Offline snapshot of RuneLite's task families; no dependency on its private Task enum. */
final class SlayerTaskCatalogue
{
    private static volatile Map<String, List<String>> TASKS;

    static synchronized void initialize(Gson gson)
    {
        if (TASKS == null) TASKS = load(gson);
    }

    private static final class Pack
    {
        Map<String, List<String>> tasks;
    }

    private static Map<String, List<String>> load(Gson gson)
    {
        try (InputStream in = SlayerTaskCatalogue.class.getResourceAsStream("/slayer-data/tasks.json"))
        {
            if (in == null) throw new IllegalStateException("Missing Slayer task definitions");
            Pack pack = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Pack.class);
            Map<String, List<String>> tasks = new LinkedHashMap<>();
            for (Map.Entry<String, List<String>> entry : pack.tasks.entrySet())
            {
                List<String> names = new ArrayList<>();
                names.add(normalize(entry.getKey()));
                names.add(singular(entry.getKey()));
                for (String name : entry.getValue())
                {
                    names.add(normalize(name));
                    names.add(singular(name));
                }
                if (normalize(entry.getKey()).equals("lesser nagua")) names.add("earthen nagua");
                tasks.put(normalize(entry.getKey()), Collections.unmodifiableList(names));
            }
            return Collections.unmodifiableMap(tasks);
        }
        catch (java.io.IOException ex)
        {
            throw new IllegalStateException("Cannot load Slayer task definitions", ex);
        }
    }

    static String normalize(String value)
    {
        String n = value == null ? "" : value.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
        return n.startsWith("the ") ? n.substring(4) : n;
    }

    static String singular(String value)
    {
        String n = normalize(value);
        if (n.equals("wolves")) return "wolf";
        if (n.equals("werewolves")) return "werewolf";
        if (n.equals("dwarves")) return "dwarf";
        if (n.equals("elves")) return "elf";
        if (n.equals("aviansies")) return "aviansie";
        if (n.equals("zombies")) return "zombie";
        if (n.endsWith(" axes")) return n.substring(0, n.length() - 1);
        if (n.endsWith("ies")) return n.substring(0, n.length() - 3) + "y";
        if (n.endsWith("sses") || n.endsWith("xes")) return n.substring(0, n.length() - 2);
        if (n.endsWith("s") && !n.endsWith("ss")) return n.substring(0, n.length() - 1);
        return n;
    }

    static boolean knownTask(String task)
    {
        return TASKS.containsKey(normalize(task));
    }

    static int taskCount() { return TASKS.size(); }

    static boolean matches(String task, MonsterDefinition monster)
    {
        String name = normalize(monster.getName());
        String version = normalize(monster.getVersion());
        // These combat fixtures are not repeatable assignment alternatives.
        if (name.contains("(construction)") || name.startsWith("reanimated ") || name.startsWith("scarred ")
            || name.contains("(the scar)") || version.equals("whirlpool") || version.startsWith("idle")
            || version.equals("quest")
            || version.startsWith("quest,") || version.contains("(quest)")) return false;
        if (KonarTargetCatalogue.listed(task, monster)) return true;
        List<String> names = TASKS.get(normalize(task));
        if (names == null) names = Collections.singletonList(singular(task));
        for (String root : names)
        {
            if (!root.isEmpty() && (name.equals(root) || name.startsWith(root + " ")
                || name.endsWith(" " + root) || name.contains(" " + root + " ")
                || name.startsWith(root + "-"))) return true;
        }
        return false;
    }
}

package com.personalbis;

/** Current (Summer Sweep-Up 2026) Soulreaper axe auto-attack stack mechanics. */
public final class SoulreaperAxeEffects {
    private SoulreaperAxeEffects(){}

    public static final int MAX_STACKS = 5;

    public static boolean isSoulreaper(EquipmentCandidate w){
        if(w==null||w.getItem()==null||w.getItem().getName()==null)return false;
        return w.getItem().getName().toLowerCase().contains("soulreaper axe");
    }

    public static int clampStacks(int stacks){ return Math.max(0,Math.min(MAX_STACKS,stacks)); }

    /**
     * Each Soul stack contributes a separate 6% of the boosted Strength level.
     * Prayer and Soul-stack contributions are floored independently, then stance
     * and +8 are added. This ordering is required by the Wiki calculator's
     * 0..5-stack boundary cases (notably 4 stacks). Void, if present, is last.
     */
    public static int effectiveStrength(int boostedStrength,double prayerMultiplier,int stanceBoost,boolean voidMelee,int stacks){
        int strength=Math.max(1,boostedStrength);
        int prayerLevel=(int)Math.floor(strength*prayerMultiplier);
        int soulBonus=(int)Math.floor(strength*0.06*clampStacks(stacks));
        int e=prayerLevel+soulBonus+stanceBoost+8;
        return voidMelee?(int)Math.floor(e*1.10):e;
    }

    /**
     * Fight-length-aware auto-attack DPS from a zero-stack start.  The first
     * five swings use stack states 0..4; all later swings use state 5.
     * Expected damage is used continuously for the final partial attack so
     * optimizer ranking does not jump at arbitrary whole-attack HP boundaries.
     */
    public static double rampDps(double[] expectedDamageByStack,int targetHp,double secondsPerAttack){
        if(expectedDamageByStack==null||expectedDamageByStack.length<6||secondsPerAttack<=0)return 0.0;
        double hp=Math.max(1,targetHp);
        double dealt=0.0, attacks=0.0;
        for(int st=0;st<5;st++){
            double ev=Math.max(0.0,expectedDamageByStack[st]);
            if(ev<=0.0)continue;
            if(dealt+ev>=hp){ attacks+=(hp-dealt)/ev; return hp/(attacks*secondsPerAttack); }
            dealt+=ev; attacks+=1.0;
        }
        double sustained=Math.max(0.0,expectedDamageByStack[5]);
        if(sustained<=0.0)return 0.0;
        attacks+=(hp-dealt)/sustained;
        return hp/(attacks*secondsPerAttack);
    }

    public static int maxHit(int boostedStrength,double prayerMultiplier,int stanceBoost,boolean voidMelee,int stacks,int strengthBonus){
        int eff=effectiveStrength(boostedStrength,prayerMultiplier,stanceBoost,voidMelee,stacks);
        return (int)Math.floor(0.5 + eff*(strengthBonus+64)/640.0);
    }
}

package com.personalbis;

/** A separate, single-special burst score; never modifies the ordinary loadout's DPS. */
final class SpecWeaponRecommendation
{
    final EquipmentCandidate weapon,ammo;
    final double dps,damage;
    final int maximum,energy,ticks;
    final String style,note;
    SpecWeaponRecommendation(EquipmentCandidate weapon,EquipmentCandidate ammo,double damage,int maximum,int energy,int ticks,String style,String note){
        this.weapon=weapon;this.ammo=ammo;this.damage=damage;this.maximum=maximum;this.energy=energy;this.ticks=ticks;
        this.dps=damage/(ticks*.6);this.style=style;this.note=note;
    }
    SpecWeaponRecommendation withCoverage(String omitted){
        return new SpecWeaponRecommendation(weapon,ammo,damage,maximum,energy,ticks,style,
            note+(omitted.isEmpty()?"":" | Unmodelled owned specials: "+omitted));
    }
}

package com.personalbis;

import java.util.*;
import net.runelite.api.Skill;
import com.personalbis.wiki.WikiEquipment;

/** Scores a weapon/ammo switch in the displayed armour, separately from auto-attack optimization. */
final class SpecWeaponRecommender
{
    private static final List<String> RANGED=Arrays.asList("Magic shortbow","Magic shortbow (i)","Dark bow","Toxic blowpipe","Webweaver bow","Heavy ballista","Light ballista","Dragon knife","Zaryte crossbow");
    private static final List<String> MAGIC=Arrays.asList("Eye of Ayak","Zorya's tome","Volatile Nightmare staff","Eldritch Nightmare staff");
    private final AccountSnapshot account;
    SpecWeaponRecommender(AccountSnapshot account){this.account=account;}
    static String name(EquipmentCandidate c){WikiEquipment w=WikiEquipmentEngine.canonicalItem(c.getItem().getItemId());return w==null?c.getItem().getName():w.name;}
    SpecWeaponRecommendation best(Map<EquipmentSlot,EquipmentCandidate> worn,
        Map<AttackStyle,Map<EquipmentSlot,List<EquipmentCandidate>>> owned,AttackStyle selected,MonsterDefinition target,boolean task)
    {
        if(worn.isEmpty()||TargetStyleImmunity.immune(target,selected))return null;
        SpecWeaponRecommendation best=null;
        Set<String> omitted=new TreeSet<>();
        AttackStyle[] styles=selected==AttackStyle.MAGIC||selected==AttackStyle.RANGED?new AttackStyle[]{selected}
            :new AttackStyle[]{AttackStyle.MELEE_STAB,AttackStyle.MELEE_SLASH,AttackStyle.MELEE_CRUSH};
        for(AttackStyle style:styles){
            Map<EquipmentSlot,List<EquipmentCandidate>> ranked=owned.get(style);
            if(ranked==null)continue;
            for(EquipmentCandidate weapon:ranked.getOrDefault(EquipmentSlot.WEAPON,Collections.emptyList())){
                if(weapon.getItem().getQuantity()<=0||weapon.getRequirementResult().isBlocked())continue;
                String weaponName=name(weapon);
                boolean supported=style==AttackStyle.MAGIC?MAGIC.contains(weaponName):style==AttackStyle.RANGED?RANGED.contains(weaponName):SpecialAttackRules.MELEE.contains(weaponName);
                if(!supported){if(WikiEquipmentEngine.WEAPON_SPEC_COSTS.containsKey(weaponName))omitted.add(weaponName);continue;}
                Map<EquipmentSlot,EquipmentCandidate> gear=new EnumMap<>(EquipmentSlot.class);
                for(Map.Entry<EquipmentSlot,EquipmentCandidate> slot:worn.entrySet()){
                    for(EquipmentCandidate c:ranked.getOrDefault(slot.getKey(),Collections.emptyList()))
                        if(c.getItem().getItemId()==slot.getValue().getItem().getItemId()){gear.put(slot.getKey(),c);break;}
                }
                gear.put(EquipmentSlot.WEAPON,weapon);
                if(weapon.isTwoHanded())gear.remove(EquipmentSlot.SHIELD);
                List<EquipmentCandidate> ammo=new ArrayList<>();
                if(style==AttackStyle.RANGED&&(RangedAmmoRules.requiresEquippedAmmo(weapon)||RangedAmmoRules.usesLoadedDarts(weapon))){
                    for(EquipmentSlot slot:new EquipmentSlot[]{EquipmentSlot.AMMO,EquipmentSlot.WEAPON})
                        for(EquipmentCandidate c:ranked.getOrDefault(slot,Collections.emptyList()))
                            if(!c.getRequirementResult().isBlocked()&&c.getItem().getQuantity()>0&&RangedAmmoRules.compatible(weapon,c)
                                &&(!RangedAmmoRules.usesLoadedDarts(weapon)||BlowpipeAmmoCandidates.matches(weapon,c)))ammo.add(c);
                    if(ammo.isEmpty())continue;
                }else ammo.add(null);
                for(EquipmentCandidate a:ammo){
                    if(a!=null)gear.put(EquipmentSlot.AMMO,a);
                    SpecWeaponRecommendation r=style==AttackStyle.MAGIC?magic(gear,target,task)
                        :style==AttackStyle.RANGED?ranged(gear,target,task):melee(gear,style,target,task);
                    if(r!=null&&r.dps>0&&Double.isFinite(r.dps)&&(best==null||r.dps>best.dps))best=r;
                }
            }
        }
        return best==null?null:best.withCoverage(String.join(", ",omitted));
    }
    private SpecWeaponRecommendation result(EquipmentCandidate w,HitDistribution.AttackDistribution d,int ticks,AttackStyle style,
        Map<EquipmentSlot,EquipmentCandidate> gear,String note){
        String n=name(w);int cost=WikiEquipmentEngine.WEAPON_SPEC_COSTS.getOrDefault(n,50);
        EquipmentCandidate ammo=gear.get(EquipmentSlot.AMMO);
        if(ammo!=null&&style==AttackStyle.RANGED)note+=" | Ammo: "+ammo.getItem().getName()+(RangedAmmoRules.usesLoadedDarts(w)?" (manual assumption)":"");
        return new SpecWeaponRecommendation(w,ammo,d.expectedDamage(),d.max(),cost,ticks,style.toString(),note);
    }
    private MeleePrayer meleePrayer(){
        int p=account.real(Skill.PRAYER);
        if(account.isZealUnlocked())return MeleePrayer.ZEAL;
        if(p>=70&&account.isPietyUnlocked())return MeleePrayer.PIETY;
        if(p>=60&&account.isChivalryUnlocked())return MeleePrayer.CHIVALRY;
        return p>=44?MeleePrayer.HIGH:p>=31?MeleePrayer.MID:p>=13?MeleePrayer.LOW:MeleePrayer.NONE;
    }
    private RangedPrayer rangedPrayer(){
        int p=account.real(Skill.PRAYER);
        if(p>=74&&account.isRigourUnlocked())return RangedPrayer.RIGOUR;
        if(p>=62&&account.isDeadeyeUnlocked())return RangedPrayer.DEADEYE;
        return p>=44?RangedPrayer.EAGLE_EYE:p>=26?RangedPrayer.HAWK_EYE:p>=8?RangedPrayer.SHARP_EYE:RangedPrayer.NONE;
    }
    private SpecWeaponRecommendation melee(Map<EquipmentSlot,EquipmentCandidate> gear,AttackStyle style,MonsterDefinition m,boolean task){
        EquipmentCandidate w=gear.get(EquipmentSlot.WEAPON);String n=name(w);
        if(!SpecialAttackRules.MELEE.contains(n)||!MeleeAttackStyleResolver.supports(w,style)
            ||!WikiTargetEligibility.meleeCanDamage(m,w)||!LeafyTargetRules.meleeCanDamage(m,w)||!VampyreTargetRules.canDamageMelee(gear,w,m))return null;
        SpecWeaponRecommendation best=null;
        for(MeleeStance stance:MeleeAttackStyleResolver.legalStances(w,style)){
            CombatResult base=new MeleeCombatCalculator(account).calculateSnapshotForStance(gear,style,m,task,stance,meleePrayer());
            int roll=base.getAttackRoll()*SpecialAttackRules.attackPercent(n)/100;
            double accuracy=WikiAccuracyRoll.normal(roll,base.getDefenceRoll());
            if(n.equals("Osmumten's fang")&&style==AttackStyle.MELEE_STAB)
                accuracy=RaidScaling.isToa(m)?1-Math.pow(1-accuracy,2):WikiAccuracyRoll.fang(roll,base.getDefenceRoll());
            if(RaidCombatRules.core(m))accuracy=1;
            accuracy=WikiPlayerVsNpcCalc.targetAccuracy(m,accuracy);
            int max=(int)Math.floor(base.getPreWeaponMaxHit()*MeleeLoadoutEffects.inquisitorMultiplier(gear,style));
            HitDistribution.AttackDistribution d=SpecialAttackRules.melee(n,max,accuracy,
                WikiAccuracyRoll.normal(roll*3/4,base.getDefenceRoll()),m==null?1:m.getSize());
            AttackStyle damageStyle=n.equals("Voidwaker")?AttackStyle.MAGIC:style;
            if(n.equals("Voidwaker")&&!WikiTargetEligibility.magicCanDamage(m))continue;
            if(RaidCombatRules.core(m))d=SpecialAttackRules.single(HitDistribution.single(d.max(),true));
            d=WikiPlayerVsNpcCalc.applyCorp(d,m,w,damageStyle);
            d=WikiPlayerVsNpcCalc.finalDistribution(d,m,damageStyle,w,null,false,gear.values());
            if(VampyreTargetRules.tier2HalfDamage(gear,w,m))d=d.transform(HitDistribution.divide(2,0),true);
            SpecWeaponRecommendation r=result(w,d,base.getAttackSpeed(),style,gear,"Special stance: "+CombatStyleLabels.description(w,style,stance)+"; no utility/drain value");
            if(best==null||r.dps>best.dps)best=r;
        }
        return best;
    }
    private SpecWeaponRecommendation magic(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task){
        EquipmentCandidate w=gear.get(EquipmentSlot.WEAPON);String n=name(w);
        if(w.getItem().getItemId()==34727||!MAGIC.contains(n)||!WikiTargetEligibility.magicCanDamage(m)||!LeafyTargetRules.poweredMagicCanDamage(m))return null;
        int level=Math.max(1,RaidScaling.boosted(account,Skill.MAGIC,m));
        int base=n.equals("Zorya's tome")?Math.max(1,level/3-10):n.equals("Eye of Ayak")?Math.max(1,level/3-6)*13/10
            :n.startsWith("Volatile")?Math.max(1,Math.min(58,(99+58*level)/99)):Math.max(1,Math.min(44,(99+44*level)/99));
        int bonus=0;double damage=0;for(EquipmentCandidate c:gear.values()){bonus+=c.getMagicAttack();damage+=c.getMagicDamage();}
        WikiEquipmentEngine.Totals totals=WikiEquipmentEngine.transform(gear,m,null,0,0,bonus,damage,0);
        MagicPrayer prayer=MagicPrayer.best(account);
        int roll=(PoweredStaff.forWeapon(w.getItem().getName())!=null
            ?WikiMagicAccuracy.calculatePoweredAccurate(level,prayer.accuracy,totals.magicAttack,gear.values(),m,task)
            :WikiMagicAccuracy.calculate(level,prayer.accuracy,totals.magicAttack,gear.values(),m,null,task)).attackRoll;
        roll=roll*(n.equals("Zorya's tome")?250:n.equals("Eye of Ayak")?200:n.startsWith("Volatile")?150:100)/100;
        int defence=RaidScaling.defenceRoll(m,m==null?640:(Math.max(0,m.getMagicLevel())+9)*(m.getMagicDefence()+64));
        int max=WikiMagicDamage.powered(base,totals.magicDamage,prayer.damage,gear.values(),m,task).maxHit;
        if(n.equals("Zorya's tome"))max=max*160/100;
        double accuracy=WikiPlayerVsNpcCalc.targetAccuracy(m,WikiAccuracyRoll.normal(roll,defence));int min=0;
        if(RaidCombatRules.wardenP2(m)){int[] bounds=RaidCombatRules.wardenBounds(max,roll,defence);min=bounds[0];max=bounds[1];accuracy=1;}
        Double brimstone=null;
        if(!RaidCombatRules.wardenP2(m))for(EquipmentCandidate c:gear.values())if(name(c).equals("Brimstone ring"))brimstone=WikiAccuracyRoll.normal(roll,defence*9/10);
        HitDistribution.AttackDistribution d=WikiPlayerVsNpcCalc.magicFinalDistribution(min,max,accuracy,brimstone,m,gear.values(),null);
        return result(w,d,n.equals("Zorya's tome")?3:5,AttackStyle.MAGIC,gear,n.equals("Zorya's tome")?"Zorya's flow: initial hit only; follow-up attacks, stored buffs and rotations excluded":"Built-in special spell; direct damage only");
    }
    private SpecWeaponRecommendation ranged(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task){
        EquipmentCandidate w=gear.get(EquipmentSlot.WEAPON),a=gear.get(EquipmentSlot.AMMO);String n=name(w);
        if(!RANGED.contains(n)
            ||!WikiTargetEligibility.rangedCanDamage(m)||!LeafyTargetRules.rangedCanDamage(m,a)||!VampyreTargetRules.canDamageRanged(gear,w,a,m))return null;
        SpecWeaponRecommendation best=null;
        for(RangedStance stance:CombatStyleLabels.rangedStances(w.getWeaponCategory())){
            RangedCombatResult base=new RangedCombatCalculator(account).calculateSnapshot(gear,m,task,stance,rangedPrayer());
            int roll=base.getAttackRoll();
            if(n.startsWith("Magic shortbow"))roll=roll*10/7;
            else if(n.contains("ballista"))roll=roll*5/4;
            else if(n.equals("Toxic blowpipe")||n.equals("Webweaver bow")||n.equals("Zaryte crossbow"))roll*=2;
            double accuracy=WikiPlayerVsNpcCalc.targetAccuracy(m,WikiAccuracyRoll.normal(roll,base.getDefenceRoll()));int max=base.getPreTransformMax(),min=0,hits=1;
            if(n.startsWith("Magic shortbow")){
                if(a==null)continue;
                max=WikiIntegerStages.maxHitFromEffective(RaidScaling.boosted(account,Skill.RANGED,m)+10,a.getRangedStrength()+64);hits=2;
            }else if(n.equals("Toxic blowpipe"))max=max*3/2;
            else if(n.contains("ballista"))max=max*5/4;
            else if(n.equals("Webweaver bow")){max-=max*6/10;hits=4;}
            else if(n.equals("Dragon knife"))hits=2;
            else if(n.equals("Dark bow")){boolean dragon=a!=null&&a.getItem().getName().toLowerCase().contains("dragon arrow");min=dragon?8:5;max=Math.min(48,max*(dragon?15:13)/10);hits=2;}
            if(RaidCombatRules.wardenP2(m)){int[] bounds=RaidCombatRules.wardenBounds(max,roll,base.getDefenceRoll());min=bounds[0];max=bounds[1];accuracy=1;}
            HitDistribution hit=n.equals("Zaryte crossbow")
                ?SpecialBoltRules.distribution(a,m,RaidScaling.boosted(account,Skill.RANGED,m),min,max,accuracy,account.isKandarinHardCompleted(),CorporealBeastRules.isCorp(m))
                :HitDistribution.linear(accuracy,min,Math.max(min,max)).accurateZeroToOne();
            List<HitDistribution> splats=new ArrayList<>();for(int i=0;i<hits;i++)splats.add(hit);
            HitDistribution.AttackDistribution d=new HitDistribution.AttackDistribution(splats);
            if(!n.equals("Zaryte crossbow"))d=WikiPlayerVsNpcCalc.applyCorp(d,m,w,AttackStyle.RANGED);
            d=WikiPlayerVsNpcCalc.finalDistribution(d,m,AttackStyle.RANGED,w,null,false,gear.values());
            SpecWeaponRecommendation r=result(w,d,base.getAttackSpeed(),AttackStyle.RANGED,gear,"Special stance: "+stance+"; no healing/burn value; ruby uses the selected starting HP");
            if(best==null||r.dps>best.dps)best=r;
        }
        return best;
    }
}

package com.personalbis;

import java.util.*;

/** Direct-damage special distributions. Source: Wiki PlayerVsNPCCalc and dists/claws.ts (GPL-3.0).
 * Utility, defence drains, burns, regeneration and rotations are intentionally not credited. */
final class SpecialAttackRules
{
    private SpecialAttackRules() {}
    static final Set<String> MELEE=new HashSet<>(Arrays.asList("Dragon dagger","Abyssal dagger","Dragon claws",
        "Armadyl godsword","Bandos godsword","Saradomin godsword","Zamorak godsword","Voidwaker",
        "Dragon mace","Dragon sword","Dragon longsword","Dragon scimitar","Abyssal whip","Dragon warhammer",
        "Elder maul","Barrelchest anchor","Dragon halberd","Crystal halberd","Granite hammer","Osmumten's fang"));
    static int attackPercent(String name){
        if(name.endsWith("godsword")||name.equals("Barrelchest anchor"))return 200;
        if(name.equals("Osmumten's fang")||name.equals("Granite hammer"))return 150;
        if(name.equals("Dragon dagger"))return 115;
        if(Arrays.asList("Elder maul","Dragon mace","Dragon sword","Dragon scimitar","Abyssal whip","Abyssal dagger").contains(name))return 125;
        return 100;
    }
    static int maxHit(String name,int max){
        if(name.endsWith("godsword"))max=max*11/10;
        if(name.equals("Bandos godsword"))return max*11/10;
        if(Arrays.asList("Armadyl godsword","Dragon sword","Dragon longsword").contains(name))return max*5/4;
        if(name.equals("Dragon mace")||name.equals("Dragon warhammer"))return max*3/2;
        if(name.equals("Dragon dagger"))return max*23/20;
        if(name.equals("Abyssal dagger"))return max*17/20;
        if(name.equals("Dragon halberd")||name.equals("Crystal halberd")||name.equals("Barrelchest anchor"))return max*11/10;
        return max;
    }
    static HitDistribution.AttackDistribution melee(String name,int baseMax,double accuracy,double secondAccuracy,int size){
        int max=maxHit(name,baseMax);
        if(name.equals("Dragon claws"))return claws(accuracy,max);
        if(name.equals("Voidwaker"))return single(HitDistribution.linear(1,baseMax/2,baseMax+baseMax/2));
        if(name.equals("Osmumten's fang"))return single(HitDistribution.linear(accuracy,baseMax*3/20,baseMax).accurateZeroToOne());
        HitDistribution hit=HitDistribution.linear(accuracy,0,max).accurateZeroToOne();
        if(name.equals("Granite hammer"))hit=hit.transform(HitDistribution.flatAdd(5,0),true);
        if(name.equals("Dragon dagger"))return new HitDistribution.AttackDistribution(Arrays.asList(hit,hit));
        if(name.equals("Abyssal dagger")){
            List<HitDistribution.WeightedHit> out=new ArrayList<>();
            HitDistribution raw=HitDistribution.linear(accuracy,0,max).accurateZeroToOne();
            for(HitDistribution.WeightedHit h:raw.hits()){
                if(h.hitsplats.get(0).accurate)for(HitDistribution.WeightedHit h2:HitDistribution.linear(1,0,max).accurateZeroToOne().hits()){
                    List<HitDistribution.Hitsplat> splats=new ArrayList<>(h.hitsplats);splats.addAll(h2.hitsplats);
                    out.add(new HitDistribution.WeightedHit(h.probability*h2.probability,splats));
                }else out.add(h);
            }
            return single(new HitDistribution(out));
        }
        if(size>1&&(name.equals("Dragon halberd")||name.equals("Crystal halberd")))return new HitDistribution.AttackDistribution(
            Arrays.asList(hit,HitDistribution.linear(secondAccuracy,0,max).accurateZeroToOne()));
        return single(hit);
    }
    static HitDistribution.AttackDistribution single(HitDistribution d){return new HitDistribution.AttackDistribution(Collections.singletonList(d));}
    static HitDistribution.AttackDistribution claws(double accuracy,int max){
        if(max<=0)return single(HitDistribution.single(0,false));
        List<HitDistribution.WeightedHit> out=new ArrayList<>();
        for(int failed=0;failed<4;failed++){
            int low=max*(4-failed)/4,high=max+low-1;
            double p=Math.pow(1-accuracy,failed)*accuracy/(high-low+1);
            for(int total=low;total<=high;total++){
                int[] hits=failed==0?new int[]{total/2,total/4,total/8,total/8+1}
                    :failed==1?new int[]{total/2,total/4,total/4+1}
                    :failed==2?new int[]{total/2,total/2+1}:new int[]{total+1};
                List<HitDistribution.Hitsplat> splats=new ArrayList<>();
                for(int h:hits)splats.add(new HitDistribution.Hitsplat(h,true));
                out.add(new HitDistribution.WeightedHit(p,splats));
            }
        }
        double fail=Math.pow(1-accuracy,4);
        out.add(new HitDistribution.WeightedHit(fail*2/3,Arrays.asList(new HitDistribution.Hitsplat(1,false),new HitDistribution.Hitsplat(1,false))));
        out.add(new HitDistribution.WeightedHit(fail/3,Collections.singletonList(new HitDistribution.Hitsplat(0,false))));
        return single(new HitDistribution(out).flatten());
    }
}

package com.personalbis;

import java.util.*;

/** Zaryte special: a successful accuracy roll forces its enchanted-bolt effect.
 * Wiki dists/bolts.ts ordering: non-ruby, accurate-zero, Corp, ruby, NPC transforms. */
final class SpecialBoltRules
{
    private SpecialBoltRules(){}
    static HitDistribution distribution(EquipmentCandidate ammo,MonsterDefinition m,int level,int min,int max,
        double accuracy,boolean diary,boolean corp){
        String n=m!=null&&EnchantedBoltEffects.enchanted(ammo)?ammo.getItem().getName().toLowerCase(Locale.ROOT):"";
        HitDistribution d=HitDistribution.linear(accuracy,min,max);
        boolean dragonBlocked=m!=null&&(m.hasAttribute("dragon")||m.hasAttribute("fiery")||m.hasAttribute("dragonfire immune"));
        if(n.contains("diamond"))d=replacement(d,HitDistribution.linear(1,0,max*126/100),.10*(diary?1.1:1),false);
        else if(n.contains("onyx")&&!m.hasAttribute("undead"))d=replacement(d,HitDistribution.linear(1,0,max*132/100),.11*(diary?1.1:1),true);
        else if(n.contains("opal"))d=bonus(d,level/9,.05*(diary?1.1:1),false);
        else if(n.contains("pearl"))d=bonus(d,level/(m.hasAttribute("fiery")?13:18),.06*(diary?1.1:1),false);
        else if(n.contains("dragonstone")&&!dragonBlocked)d=bonus(d,level*2/9,.06*(diary?1.1:1),true);
        d=d.accurateZeroToOne();
        if(corp)d=d.transform(HitDistribution.divide(2,0));
        if(n.contains("ruby")){
            int cap=m.getId()==14779?66:110;
            d=replacement(d,HitDistribution.single(Math.min(cap,m.getHitpoints()*22/100),true),.06*(diary?1.1:1),false);
        }
        return d.flatten();
    }
    private static HitDistribution replacement(HitDistribution base,HitDistribution effect,double p,boolean accurateOnly){
        return base.transform(h->{
            if(h.accurate)return effect;
            if(accurateOnly)return HitDistribution.single(h.damage,false);
            List<HitDistribution.WeightedHit> out=new ArrayList<>();
            for(HitDistribution.WeightedHit e:effect.hits())out.add(new HitDistribution.WeightedHit(p*e.probability,e.hitsplats));
            out.add(new HitDistribution.WeightedHit(1-p,Collections.singletonList(h)));return new HitDistribution(out);
        });
    }
    private static HitDistribution bonus(HitDistribution base,int extra,double p,boolean accurateOnly){
        return base.transform(h->{
            if(h.accurate)return HitDistribution.single(h.damage+extra,true);
            if(accurateOnly)return HitDistribution.single(h.damage,false);
            return new HitDistribution(Arrays.asList(
                new HitDistribution.WeightedHit(p,Collections.singletonList(new HitDistribution.Hitsplat(h.damage+extra,false))),
                new HitDistribution.WeightedHit(1-p,Collections.singletonList(h))));
        });
    }
}

