/** Runtime labels and combat states; the upstream monster snapshot stays intact. */
final class TheatreOfBloodRules
{
    private static final List<String> BOSSES = Arrays.asList("The Maiden of Sugadinti",
        "Pestilent Bloat", "Nylocas Vasilias", "Sotetseg", "Xarpus", "Verzik Vitur", "Nylocas Prinkipas");

    private TheatreOfBloodRules() {}

    static boolean isBoss(String name)
    {
        return BOSSES.contains(name);
    }

    static String label(String name, String version)
    {
        if (!isBoss(name)) return version;
        String raw = version == null ? "" : version.trim();
        if (name.equals("Nylocas Prinkipas")) return "Hard Mode, " + raw + " form";
        String lower = raw.toLowerCase(Locale.ROOT);
        String mode = lower.contains("entry") ? "Entry Mode"
            : lower.contains("hard") ? "Hard Mode" : "Normal Mode";
        int phase = lower.indexOf("phase ");
        if (phase >= 0) return mode + ", Phase " + raw.substring(phase + 6);
        if (lower.contains("health")) return mode + ", " + raw;
        return mode;
    }

    static List<String> versions(String name, String version)
    {
        String labelled = label(name, version);
        if ("Nylocas Vasilias".equals(name))
            return Arrays.asList(labelled + ", Melee form", labelled + ", Ranged form", labelled + ", Magic form");
        return Collections.singletonList(labelled);
    }

    /** RuneLite gameval NpcID: each Vasilias mode has three consecutive combat forms. */
    static int npcId(int id,String name,String version)
    {
        if(!"Nylocas Vasilias".equals(name)||(id!=8354&&id!=10786&&id!=10807))return id;
        String v=version.toLowerCase(Locale.ROOT);
        return id+(v.endsWith("melee form")?1:v.endsWith("magic form")?2:v.endsWith("ranged form")?3:0);
    }

    /** Keep equal-stat difficulties and style-locked forms distinct in the picker. */
    static String catalogueKey(MonsterDefinition monster)
    {
        return isBoss(monster.getName()) ? "|tob|" + monster.getVersion().toLowerCase(Locale.ROOT) : "";
    }

    static boolean phaseOne(MonsterDefinition monster)
    {
        if (monster == null || !"Verzik Vitur".equals(monster.getName())) return false;
        switch (monster.getId())
        {
            case 10830: case 10831: case 10832:
            case 8369: case 8370: case 8371:
            case 10847: case 10848: case 10849: return true;
            default: return false;
        }
    }

    static boolean canDamage(MonsterDefinition monster, AttackStyle style)
    {
        if (monster == null || !("Nylocas Vasilias".equals(monster.getName())
            || "Nylocas Prinkipas".equals(monster.getName()))) return true;
        String version = monster.getVersion().toLowerCase(Locale.ROOT);
        if (version.endsWith("magic form")) return style == AttackStyle.MAGIC;
        if (version.endsWith("ranged form")) return style == AttackStyle.RANGED;
        if (version.endsWith("melee form")) return style != AttackStyle.MAGIC && style != AttackStyle.RANGED;
        return true;
    }
}

package com.personalbis;

/**
 * Tormented Demon phase rules, matching the OSRS Wiki DPS calculator
 * (PlayerVsNPCCalc and BaseCalc.tdUnshieldedBonusApplies).
 */
final class TormentedDemonRules
{
    private TormentedDemonRules() {}

    enum Phase
    {
        SHIELDED("Shielded"),
        DEFENCELESS("Shielded (Defenceless)"),
        UNSHIELDED("Unshielded");

        private final String label;
        Phase(String label) { this.label = label; }
        @Override public String toString() { return label; }
    }

    static boolean isTormentedDemon(MonsterDefinition m)
    {
        return m != null && "Tormented Demon".equalsIgnoreCase(m.getName());
    }

    /** The selected phase is carried as the target's version, like Bork's phases. */
    static MonsterDefinition withPhase(MonsterDefinition m, Phase phase)
    {
        if (!isTormentedDemon(m) || phase == null) return m;
        return new MonsterDefinition(m.getId(), m.getName(), phase.toString(), m.getCombatLevel(),
            m.getDefenceLevel(), m.getMagicLevel(), m.getRangedLevel(), m.getHitpoints(),
            m.getStabDefence(), m.getSlashDefence(), m.getCrushDefence(), m.getMagicDefence(),
            m.getLightDefence(), m.getStandardDefence(), m.getHeavyDefence(), m.getAttributes(),
            m.getSize(), m.getWeaknessElement(), m.getWeaknessSeverity(), m.getMagicAttack());
    }

    /** Phase of a Tormented Demon target; Shielded when none was chosen. */
    static Phase phase(MonsterDefinition m)
    {
        if (!isTormentedDemon(m)) return null;
        for (Phase phase : Phase.values())
            if (phase.toString().equalsIgnoreCase(m.getVersion())) return phase;
        return Phase.SHIELDED;
    }

    /** Every attack hits unless the demon is Shielded. */
    static double accuracy(MonsterDefinition m, double ordinaryAccuracy)
    {
        Phase phase = phase(m);
        return phase != null && phase != Phase.SHIELDED ? 1.0 : ordinaryAccuracy;
    }

    /** 20% damage reduction while shielded, unless using demonbane or (melee) abyssal weapons. */
    static boolean damageReduced(MonsterDefinition m, AttackStyle style, String weaponName, boolean demonbaneSpell)
    {
        Phase phase = phase(m);
        if (phase == null || phase == Phase.UNSHIELDED) return false;
        return !usingDemonbane(style, weaponName, demonbaneSpell) && !usingAbyssal(style, weaponName);
    }

    /**
     * Unshielded bonus: spells, heavy ranged (crossbows and chinchompas) and crush
     * attacks deal ticks^2 - 16 extra damage on accurate hits and attack one tick faster.
     */
    static boolean unshieldedBonusApplies(MonsterDefinition m, AttackStyle style,
        EquipmentCandidate weapon, boolean usingSpell)
    {
        if (phase(m) != Phase.UNSHIELDED || style == null) return false;
        switch (style)
        {
            case MAGIC: return usingSpell;
            case MELEE_CRUSH: return true;
            case RANGED:
                String category = weapon == null ? "" : weapon.getWeaponCategory();
                return "Crossbow".equalsIgnoreCase(category) || "Chinchompas".equalsIgnoreCase(category);
            default: return false;
        }
    }

    static int bonusDamage(int attackTicks)
    {
        return Math.max(0, attackTicks * attackTicks - 16);
    }

    /**
     * Adds the bonus to accurate hits of a final distribution. Unshielded demons have
     * no other damage transforms, so adding it after them matches the Wiki order.
     */
    static HitDistribution.AttackDistribution withUnshieldedBonus(HitDistribution.AttackDistribution d, int attackTicks)
    {
        int bonus = bonusDamage(attackTicks);
        return bonus == 0 || d == null ? d : d.transform(HitDistribution.flatAdd(bonus, 0), false).flatten();
    }

    private static boolean usingDemonbane(AttackStyle style, String weaponName, boolean demonbaneSpell)
    {
        if (style == AttackStyle.MAGIC) return demonbaneSpell;
        if (style == AttackStyle.RANGED) return is(weaponName, "Scorching bow");
        return is(weaponName, "Silverlight", "Darklight", "Arclight", "Emberlight", "Bone claws", "Burning claws");
    }

    private static boolean usingAbyssal(AttackStyle style, String weaponName)
    {
        boolean melee = style == AttackStyle.MELEE_STAB || style == AttackStyle.MELEE_SLASH || style == AttackStyle.MELEE_CRUSH;
        return melee && is(weaponName, "Abyssal bludgeon", "Abyssal dagger", "Abyssal whip", "Abyssal tentacle");
    }

    private static boolean is(String weaponName, String... names)
    {
        if (weaponName == null) return false;
        for (String name : names) if (name.equalsIgnoreCase(weaponName)) return true;
        return false;
    }
}

package com.personalbis;

import java.util.Map;

/**
 * Wiki DPS parity: vampyre weapon eligibility and auto-attack modifiers.
 * Ported from upstream BaseCalc.wearingVampyrebane/isWearingSilverWeapon and
 * PlayerVsNPCCalc vampyre accuracy/damage/immunity stages.
 */
public final class VampyreTargetRules {
 private VampyreTargetRules(){}
 public static boolean isVampyre(MonsterDefinition m){return m!=null&&(m.hasAttribute("vampyre1")||m.hasAttribute("vampyre2")||m.hasAttribute("vampyre3"));}
 public static int tier(MonsterDefinition m){if(m==null)return 0;if(m.hasAttribute("vampyre3"))return 3;if(m.hasAttribute("vampyre2"))return 2;if(m.hasAttribute("vampyre1"))return 1;return 0;}
 private static String n(EquipmentCandidate c){return c==null||c.getItem()==null?"":c.getItem().getName().toLowerCase();}
 public static boolean has(Map<EquipmentSlot,EquipmentCandidate> gear,String needle){if(gear==null)return false;for(EquipmentCandidate c:gear.values())if(n(c).contains(needle.toLowerCase()))return true;return false;}
 public static boolean isSilverWeapon(EquipmentCandidate w){String x=n(w);return x.contains("blessed axe")||x.contains("ivandis flail")||x.contains("blisterwood flail")||x.contains("hallowed flail")||x.contains("silver sickle")||x.contains("emerald sickle")||x.contains("ruby sickle")||x.contains("blisterwood sickle")||x.contains("silverlight")||x.contains("darklight")||x.contains("arclight")||x.contains("rod of ivandis")||x.contains("wolfbane");}
 public static boolean isRangedSilver(EquipmentCandidate w,EquipmentCandidate ammo){String wn=n(w),an=n(ammo);return wn.contains("blisterwood stake")||an.contains("silver bolts");}
 public static boolean fullVampyrebane(EquipmentCandidate w,MonsterDefinition m){String x=n(w);int t=tier(m);if(t==0)return false;if(x.contains("blisterwood stake"))return true;if(t==2&&x.contains("rod of ivandis"))return true;return x.contains("ivandis flail")||x.contains("blisterwood sickle")||x.contains("blisterwood flail")||x.contains("hallowed flail")||x.contains("sunspear");}
 public static boolean canDamageMelee(Map<EquipmentSlot,EquipmentCandidate> gear,EquipmentCandidate w,MonsterDefinition m){int t=tier(m);if(t<=1)return true;if(t==3)return fullVampyrebane(w,m);return fullVampyrebane(w,m)||has(gear,"efaritay's aid")||isSilverWeapon(w);}
 public static boolean canDamageRanged(Map<EquipmentSlot,EquipmentCandidate> gear,EquipmentCandidate w,EquipmentCandidate ammo,MonsterDefinition m){int t=tier(m);if(t<=1)return true;if(t==3)return n(w).contains("blisterwood stake");return n(w).contains("blisterwood stake")||has(gear,"efaritay's aid")||isRangedSilver(w,ammo);}
 public static double meleeAccuracyMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear,EquipmentCandidate w,MonsterDefinition m){if(!isVampyre(m))return 1.0;String x=n(w);double z=1.0;if(x.contains("blisterwood flail")||x.contains("blisterwood sickle"))z*=1.05;else if(x.contains("hallowed flail")||x.contains("sunspear"))z*=1.25;if(has(gear,"efaritay's aid")&&isSilverWeapon(w))z*=1.15;return z;}
 public static double meleeDamageMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear,EquipmentCandidate w,MonsterDefinition m){if(!isVampyre(m))return 1.0;String x=n(w);double z=1.0;boolean ef=has(gear,"efaritay's aid");if(x.contains("blisterwood flail")||x.contains("hallowed flail")||x.contains("blisterwood stake"))z=1.25;else if(x.contains("sunspear"))z=1.50;else if(x.contains("blisterwood sickle"))z=1.15;else if(x.contains("ivandis flail"))z=1.20;else if(x.contains("rod of ivandis")&&tier(m)!=3)z=1.10;else if(isSilverWeapon(w)&&tier(m)==1)z=1.10;if(ef&&z>1.0)z*=1.10;return z;}
 /** Tier-2 fallback: Efaritay + non-vampyrebane deals half damage; silver without Efaritay is capped at 10. */
 public static boolean tier2HalfDamage(Map<EquipmentSlot,EquipmentCandidate> gear,EquipmentCandidate w,MonsterDefinition m){return tier(m)==2&&!fullVampyrebane(w,m)&&has(gear,"efaritay's aid");}
 public static boolean tier2SilverCap10(Map<EquipmentSlot,EquipmentCandidate> gear,EquipmentCandidate w,MonsterDefinition m){return tier(m)==2&&!fullVampyrebane(w,m)&&!has(gear,"efaritay's aid")&&isSilverWeapon(w);}
}

