/** Complete Void families are protected until the remaining slots are searched. */
final class VoidLoadoutFamilies {
 private VoidLoadoutFamilies(){}
 static List<Map<EquipmentSlot,EquipmentCandidate>> families(Map<EquipmentSlot,List<EquipmentCandidate>> ranked,EquipmentCandidate required,String helmet){
  List<Map<EquipmentSlot,EquipmentCandidate>> result=new ArrayList<>();
  for(boolean eliteBody:new boolean[]{false,true})for(boolean eliteLegs:new boolean[]{false,true}){
   Map<EquipmentSlot,EquipmentCandidate> gear=new EnumMap<>(EquipmentSlot.class);
   EquipmentSlot[] slots={EquipmentSlot.HEAD,EquipmentSlot.BODY,EquipmentSlot.LEGS,EquipmentSlot.HANDS};
   String[] names={helmet,eliteBody?"Elite void top":"Void knight top",eliteLegs?"Elite void robe":"Void knight robe","Void knight gloves"};
   boolean complete=true;
   for(int i=0;i<slots.length;i++){
    EquipmentCandidate chosen=null;
    for(EquipmentCandidate candidate:ranked.getOrDefault(slots[i],Collections.emptyList()))
     if(candidate!=null&&candidate.getItem()!=null&&!candidate.getRequirementResult().isBlocked()
       &&candidate.getItem().getQuantity()>0&&VoidEquipment.matches(candidate.getItem().getName(),names[i])){
      if(required!=null&&required.getSlot()==slots[i]&&required.getItem().getItemId()!=candidate.getItem().getItemId())continue;
      chosen=candidate;break;
     }
    if(chosen==null){complete=false;break;}gear.put(slots[i],chosen);
   }
   if(complete)result.add(Collections.unmodifiableMap(gear));
  }
  return result;
 }
}

package com.personalbis;

/**
 * OSRS Wiki DPS calculator accuracy-roll helpers.
 *
 * Parity source: src/lib/BaseCalc.ts getNormalAccuracyRoll/getFangAccuracyRoll.
 * Unlike the common positive-roll shortcut, these helpers deliberately preserve
 * signed attack/defence rolls produced by bonuses below -64.
 */
public final class WikiAccuracyRoll {
    private WikiAccuracyRoll() {}

    public static double normal(int attackRoll, int defenceRoll) {
        int atk = normalizeNegative(attackRoll);
        int def = normalizeNegative(defenceRoll);
        final double hit;
        if (atk >= 0 && def >= 0) hit = standard(atk, def);
        else if (atk >= 0) hit = 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
        else if (def >= 0) hit = 0.0;
        else hit = standard(-def, -atk);
        return clamp(hit);
    }

    public static double fang(int attackRoll, int defenceRoll) {
        int atk = normalizeNegative(attackRoll);
        int def = normalizeNegative(defenceRoll);
        final double hit;
        if (atk >= 0 && def >= 0) hit = fangStandard(atk, def);
        else if (atk >= 0) hit = 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
        else if (def >= 0) hit = 0.0;
        else hit = fangReverse(-def, -atk);
        return clamp(hit);
    }

    private static int normalizeNegative(int roll) {
        return roll < 0 ? Math.min(0, roll + 2) : roll;
    }

    private static double standard(double attack, double defence) {
        return attack > defence
            ? 1.0 - (defence + 2.0) / (2.0 * (attack + 1.0))
            : attack / (2.0 * (defence + 1.0));
    }

    private static double fangStandard(double attack, double defence) {
        return attack > defence
            ? 1.0 - (defence + 2.0) * (2.0 * defence + 3.0) / (6.0 * (attack + 1.0) * (attack + 1.0))
            : attack * (4.0 * attack + 5.0) / (6.0 * (attack + 1.0) * (defence + 1.0));
    }

    private static double fangReverse(double attack, double defence) {
        return attack < defence
            ? attack * (defence * 6.0 - 2.0 * attack + 5.0) / (6.0 * (defence + 1.0) * (defence + 1.0))
            : 1.0 - (defence + 2.0) * (2.0 * defence + 3.0) / (6.0 * (defence + 1.0) * (attack + 1.0));
    }

    private static double clamp(double value) {
        return Math.max(0.0, Math.min(1.0, value));
    }
}

