  check(DefenceReductionPlan.OFF.with(Type.DWH,999).amount(Type.DWH)==20,"bounded input");
  check(changed.getHitpoints()==500&&changed.getWeaknessSeverity()==50&&changed.getSlashDefence()==40,"context preserved");
