            JsonObject row = element.getAsJsonObject();
            String task = row.get("task").getAsString(), area = row.get("area").getAsString();
            int id = row.get("id").getAsInt();
            MonsterDefinition monster = db.findTaskVariants(task).stream().filter(m -> m.getId() == id)
                .findFirst().orElseThrow(() -> new AssertionError("Missing reviewed profile " + id));
            boolean yes = row.get("eligible").getAsBoolean();
            SlayerAssignmentLocation.Eligibility expected = yes ? SlayerAssignmentLocation.Eligibility.ELIGIBLE
                : SlayerAssignmentLocation.Eligibility.INELIGIBLE;
            if (db.taskLocationEligibility(task, monster, area) != expected)
                throw new AssertionError("Review decision mismatch " + task + "/" + area + "/" + id);
            if (db.findTaskVariants(task, area).stream().anyMatch(m -> m.getId() == id) != yes)
                throw new AssertionError("Picker mismatch " + id);
            if (ReviewedSlayerLocations.decision(task, "", monster) != null
                || ReviewedSlayerLocations.decision("Unrelated task", area, monster) != null)
                throw new AssertionError("Review leaked beyond scope " + id);
            checked++;
        }
        if (checked != 470) throw new AssertionError("Incomplete imported review");
        System.out.println("PASS all " + checked + " reviewed decisions, picker results and scope isolation");
    }
}

package com.personalbis;

import java.util.*;

/** Salve's integer checkpoint and the screenshot's ordinary Fang DPS boundary. */
public final class SalveRoundingSelfTest
{
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private static void close(double actual,double expected){if(Math.abs(actual-expected)>1e-9)throw new AssertionError(actual+" != "+expected);}
    private static Map<EquipmentSlot,EquipmentCandidate> neck(String name){
        Map<EquipmentSlot,EquipmentCandidate> gear=new EnumMap<>(EquipmentSlot.class);
        gear.put(EquipmentSlot.NECK,new EquipmentCandidate(new BankItem(12018,1,name),EquipmentSlot.NECK,0,0,0,0,0,0,0,0,0,false,"",RequirementResult.usable("fixture")));
        return gear;
    }
    public static void main(String[] args){
        MonsterDefinition undead=new MonsterDefinition(8061,"Vorkath",732,214,150,100,750,0,0,0,0,0,0,0,Arrays.asList("undead"),3,"",0);
        MonsterDefinition living=new MonsterDefinition(1,"Living",1,1,1,1,1);
        for(String name:new String[]{"Salve amulet (e)","Salve amulet(ei)","Salve amulet","Salve amulet(i)"}){
            Map<EquipmentSlot,EquipmentCandidate> gear=neck(name);
            int numerator=name.contains("(e)")||name.contains("(ei)")?6:7;
            int denominator=numerator==6?5:6;
            for(int max=0;max<=150;max++)check(MeleeLoadoutEffects.salveMaxHit(max,gear,undead)==max*numerator/denominator,"integer Salve "+name);
            check(MeleeLoadoutEffects.salveMaxHit(43,gear,living)==43,"non-undead control");
        }
        Map<EquipmentSlot,EquipmentCandidate> enhanced=neck("Salve amulet(ei)");
        int base=WikiIntegerStages.maxHitFromEffective(132,148+64);
        check(base==44,"base-hit truncation");
        check(MeleeLoadoutEffects.salveMaxHit(base,enhanced,undead)==52,"Salve cannot restore discarded fraction");
        check((int)(((132*(148+64)+320.0)/640)*1.2)==53,"old ordering counterexample");
        double chance=WikiAccuracyRoll.fang(29311,20070);
        close(chance,.8437002370446669);
        // Verified share ElysianBurningPool: Attack92, Strength99, Piety, Lunge;
        // the Wiki selected the uncharged Serp (0 Strength), total gear Strength143.
        int effectiveAttack=CombatEffectiveLevels.melee(92,1.20,0,false);
        int effectiveStrength=CombatEffectiveLevels.melee(99,1.23,3,false);
        check(MeleeLoadoutEffects.salveAttackRoll(effectiveAttack*(143+64),enhanced,undead)==29311,"share attack roll");
        int unchargedBase=WikiIntegerStages.maxHitFromEffective(effectiveStrength,143+64);
        int chargedBase=WikiIntegerStages.maxHitFromEffective(effectiveStrength,148+64);
        int faceguardBase=WikiIntegerStages.maxHitFromEffective(effectiveStrength,149+64);
        check(unchargedBase==43&&chargedBase==44&&faceguardBase==44,"share charge-state and Faceguard strength thresholds");
        HitDistribution serp=MeleeWeaponEffects.fangDistribution(MeleeLoadoutEffects.salveMaxHit(unchargedBase,enhanced,undead),chance);
        HitDistribution faceguard=MeleeWeaponEffects.fangDistribution(MeleeLoadoutEffects.salveMaxHit(faceguardBase,enhanced,undead),chance);
        check(serp.max()==44&&faceguard.max()==45,"Serp/Faceguard screenshot max boundaries");
        close(serp.expectedHit()/3,7.171452014879671);
        close(faceguard.expectedHit()/3,7.312068721053778);
        HitDistribution charged=MeleeWeaponEffects.fangDistribution(MeleeLoadoutEffects.salveMaxHit(chargedBase,enhanced,undead),chance);
        close(charged.expectedHit(),faceguard.expectedHit());
        check(charged.max()==45,"charged Serp ties Faceguard at this threshold");
        double unchargedTtk=ExpectedKillTime.seconds(new HitDistribution.AttackDistribution(Collections.singletonList(serp)),750,5);
        double chargedTtk=ExpectedKillTime.seconds(new HitDistribution.AttackDistribution(Collections.singletonList(charged)),750,5);
        check(Math.abs(unchargedTtk-106.6)<.05&&Math.abs(chargedTtk-104.6)<.05,"share finite TTK figures");
        DefenceFillPolicy.Offence better=new DefenceFillPolicy.Offence(chance,45,5,faceguard.expectedHit()/3,104.6,29311,52);
        check(!better.sameAs(new DefenceFillPolicy.Offence(chance,44,5,serp.expectedHit()/3,106.6,29311,51)),"Defence fill rejects lower-DPS Serp outcome");
        System.out.println("PASS staged Salve rounding, exact Wiki share rolls/DPS/TTK, charge states and defence-fill guard");
    }
}

package com.personalbis;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;

/**
 * Runs every standalone self-test from {@code gradle test}, so one command (and CI)
 * covers them all. Each self-test still keeps its own Gradle task for running it alone.
 *
 * <p>Each self-test runs in its own JVM, exactly like its Gradle task. Several of them
 * rely on static data being loaded fresh (for example SlayerGsonSelfTest), so sharing
 * one JVM would make results depend on test order.
 */
class SelfTestSuite
{
    private static final class SelfTest
    {
        final Class<?> type;
        final List<String> jvmArgs;

        SelfTest(Class<?> type, String... jvmArgs)
        {
            this.type = type;
            this.jvmArgs = Arrays.asList(jvmArgs);
        }
    }

    /** Programs with a main() that are deliberately not run as tests. */
    private static final Set<String> NOT_SELF_TESTS = Set.of(
        "SelfTestSuite",           // this file
        "PersonalBisPluginTest",   // launches the RuneLite dev client
        "SlayerLocationCoverage",  // writes a coverage report
        "SlayerUnresolvedAudit");  // writes an audit file

    private static final long TIMEOUT_MINUTES = 5;

    static List<SelfTest> selfTests()
    {
        return Arrays.asList(
            new SelfTest(BankWithdrawalSelfTest.class),
            new SelfTest(BlowpipeAmmoPlanSelfTest.class),
            new SelfTest(CombatSearchSelfTest.class),
            new SelfTest(CombatStyleLabelsSelfTest.class),
            new SelfTest(DefenceFillSelfTest.class),
            new SelfTest(DefenceReductionBankItemsSelfTest.class),
            new SelfTest(DefenceReductionPlanSelfTest.class),
            new SelfTest(FracturedArchiveSelfTest.class),
            new SelfTest(GroupStorageSnapshotSelfTest.class),
            new SelfTest(HpStateTtkSelfTest.class),
            new SelfTest(HueycoatlSelfTest.class),
            new SelfTest(ItemExclusionSelfTest.class),
            new SelfTest(LoadoutStatsSizingSelfTest.class),
            new SelfTest(ManualDefenceReductionSelfTest.class),
            new SelfTest(MechanicsSelfTest.class),
            new SelfTest(PoweredStanceSelfTest.class),
            new SelfTest(RaidOptionsSelfTest.class),
            new SelfTest(ReviewedSlayerLocationsSelfTest.class),
            new SelfTest(SalveRoundingSelfTest.class),
            new SelfTest(SlayerGsonSelfTest.class),
            new SelfTest(SlayerTaskSelfTest.class),
            new SelfTest(SpecialAttackSelfTest.class),
            new SelfTest(TargetStyleImmunitySelfTest.class),
            new SelfTest(TheatreOfBloodSelfTest.class),
            // Deliberately exercised with a small heap, as in its Gradle task.
            new SelfTest(TtkPerformanceSelfTest.class, "-Xmx64m"),
            new SelfTest(TwistedBowRoundingSelfTest.class),
            new SelfTest(VardorvisHpSelfTest.class),
            new SelfTest(VardorvisSelfTest.class),
            new SelfTest(VardorvisShortlistSelfTest.class),
            new SelfTest(VoidEquipmentSelfTest.class),
            new SelfTest(VoidLoadoutFamiliesSelfTest.class));
    }

    @TestFactory
    Stream<DynamicTest> selfTestsPass()
    {
        return selfTests().stream().map(test ->
            DynamicTest.dynamicTest(test.type.getSimpleName(), () -> runInFreshJvm(test)));
    }

    private static void runInFreshJvm(SelfTest test) throws Exception
    {
        String classpath = System.getProperty("selftest.classpath");
        assertTrue(classpath != null && !classpath.isEmpty(),
            "selftest.classpath is not set; run through `gradle test`");

        List<String> command = new ArrayList<>();
        command.add(Paths.get(System.getProperty("java.home"), "bin", "java").toString());
        command.add("-ea");
        command.add("-Djava.awt.headless=true");
        command.addAll(test.jvmArgs);
        command.add("-cp");
        command.add(classpath);
        command.add(test.type.getName());

        File log = File.createTempFile(test.type.getSimpleName(), ".log");
        log.deleteOnExit();
        Process process = new ProcessBuilder(command)
            .directory(new File(System.getProperty("user.dir")))
            .redirectErrorStream(true)
            .redirectOutput(log)
            .start();

        if (!process.waitFor(TIMEOUT_MINUTES, TimeUnit.MINUTES))
        {
            process.destroyForcibly();
            throw new AssertionError(test.type.getSimpleName() + " timed out after "
                + TIMEOUT_MINUTES + " minutes\n" + tail(log));
        }
        if (process.exitValue() != 0)
        {
            throw new AssertionError(test.type.getSimpleName() + " failed (exit "
                + process.exitValue() + ")\n" + tail(log));
        }
    }

    /** The last lines of a self-test's output, enough to show the failing check. */
    private static String tail(File log) throws IOException
    {
        List<String> lines = Files.readAllLines(log.toPath(), StandardCharsets.UTF_8);
        return String.join("\n", lines.subList(Math.max(0, lines.size() - 40), lines.size()));
    }

    /** Fails when a new self-test is added but not listed above, so it can't be silently skipped. */
    @Test
    void everySelfTestIsListed() throws IOException
    {
        Path dir = Paths.get("src/test/java/com/personalbis");
        Set<String> found;
        try (Stream<Path> files = Files.list(dir))
        {
            found = files
                .filter(file -> file.toString().endsWith(".java"))
                .filter(file -> read(file).contains("static void main("))
                .map(file -> file.getFileName().toString().replace(".java", ""))
                .filter(name -> !NOT_SELF_TESTS.contains(name))
                .collect(Collectors.toCollection(TreeSet::new));
        }
        Set<String> listed = selfTests().stream()
            .map(test -> test.type.getSimpleName())
            .collect(Collectors.toCollection(TreeSet::new));
        assertEquals(found, listed, "Add new self-tests to SelfTestSuite.selfTests() (or NOT_SELF_TESTS)");
    }

    private static String read(Path file)
    {
        try
        {
            return new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
        }
        catch (IOException e)
        {
            throw new IllegalStateException(e);
        }
    }
}

